fn install_method(
    vm: &mut Vm,
    table: TableId,
    name: &str,
    op: Op,
    store: &Shared,
    captures: &[Value],
) -> Result<(), Error> {
    let function = vm.new_host_function_with_data(
        callback,
        captures,
        Binding {
            store: store.clone(),
            op,
        },
    )?;
    super::put(vm, table, name, function)
}
fn table(call: &HostCall<'_>, value: Value) -> Result<TableId, Error> {
    if let Value::Table(id) = value {
        Ok(id)
    } else {
        Err(call.error(b"actor table expected"))
    }
}
fn get(call: &mut HostCall<'_>, t: TableId, key: &[u8]) -> Result<Value, Error> {
    let key = call.try_intern(key)?;
    call.raw_table_get(t, key)
}
fn bytes(call: &mut HostCall<'_>, value: Value) -> Result<Vec<u8>, Error> {
    let id = call
        .coerce_string(value)?
        .ok_or_else(|| call.error(b"string expected"))?;
    Ok(call.string_bytes(id).unwrap().to_vec())
}
fn arg(call: &HostCall<'_>, i: usize) -> Value {
    call.arguments().get(i).copied().unwrap_or(Value::Nil)
}
fn helper(call: &HostCall<'_>, index: usize) -> Result<Value, Error> {
    let Value::Table(helpers) = call.captures()[1] else {
        unreachable!()
    };
    call.raw_table_get(helpers, Value::Number(index as f64))
}
fn declared_children(store: &Shared, actor: TableId) -> Vec<TableId> {
    store.lock().unwrap().actors[&actor].children.clone()
}
fn children(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<Vec<TableId>, Error> {
    if has_native_children(store, actor) {
        native_children::children(call, store, actor)
    } else {
        Ok(declared_children(store, actor))
    }
}
fn has_native_children(store: &Shared, actor: TableId) -> bool {
    let store = store.lock().unwrap();
    let actor = &store.actors[&actor];
    actor.native_children
        || matches!(
            actor.state.class,
            "GraphDisplay"
                | "SongMeterDisplay"
                | "CourseContentsList"
                | "Model"
                | "PlayerActor"
                | "HoldJudgment"
                | "NoteField"
        )
}
fn is_frame(store: &Shared, actor: TableId) -> bool {
    matches!(
        store.lock().unwrap().actors[&actor].state.class,
        "ActorFrame"
            | "PlayerActor"
            | "HoldJudgment"
            | "PercentageDisplay"
            | "StepsDisplay"
            | "NoteField"
            | "ActorFrameTexture"
            | "WrapperState"
            | "GraphDisplay"
            | "SongMeterDisplay"
            | "CourseContentsList"
    )
}
fn sort(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    for child in declared_children(store, actor) {
        if store.lock().unwrap().actors[&child].raw_instance {
            let value = get(call, child, b"__songlua_state_draw_order")?;
            let n = sprites::number(call, value).unwrap_or(0.);
            let order = if n > -2147483649. && n < 2147483648. {
                n as i32
            } else {
                0
            };
            store
                .lock()
                .unwrap()
                .actors
                .get_mut(&child)
                .unwrap()
                .state
                .draw_order = order;
        }
    }
    let list = {
        let mut store = store.lock().unwrap();
        let mut list = store.actors[&actor].children.clone();
        list.sort_by_key(|id| store.actors[id].state.draw_order);
        store.actors.get_mut(&actor).unwrap().children = list.clone();
        list
    };
    for (index, child) in list.into_iter().enumerate() {
        call.raw_table_set(
            actor,
            Value::Number((index + 1) as f64),
            Value::Table(child),
        )?;
    }
    Ok(())
}
fn command(
    call: &mut HostCall<'_>,
    actor: TableId,
    name: &[u8],
) -> Result<Option<(Value, Vec<u8>)>, Error> {
    let mut field = [name, b"Command"].concat();
    for fallback in [false, true] {
        if fallback {
            if name.ends_with(b"Message") {
                break;
            }
            field = [name, b"MessageCommand"].concat();
        }
        let key = call.try_intern(&field)?;
        let value = call.table_get(Value::Table(actor), key)?;
        match value {
            Value::Function(_) | Value::Native(_) => return Ok(Some((value, field))),
            Value::Nil => {}
            _ => return Err(call.error(b"actor command must be a function")),
        }
    }
    Ok(None)
}
fn run(
    call: &mut HostCall<'_>,
    actor: TableId,
    function: Value,
    params: Option<Value>,
) -> Result<(), Error> {
    match params {
        Some(params) => call.call(function, &[Value::Table(actor), params])?,
        None => call.call(function, &[Value::Table(actor)])?,
    };
    Ok(())
}
fn run_scoped(
    call: &mut HostCall<'_>,
    actor: TableId,
    function: Value,
    params: Option<Value>,
) -> Result<(), Error> {
    let key = call.try_intern(b"__songlua_script_dir")?;
    let directory = call.table_get(Value::Table(actor), key)?;
    if directory == Value::Nil {
        return run(call, actor, function, params);
    }
    let directory = bytes(call, directory)?;
    let text = std::str::from_utf8(&directory)
        .map_err(|_| call.error(b"actor script directory must be UTF-8"))?;
    if text.trim().is_empty() {
        return run(call, actor, function, params);
    }
    let directory = call.try_intern(&directory)?;
    call.with_roots(&[directory, key], |call| {
        let globals = helper(call, 5)?;
        let previous = call.table_get(globals, key)?;
        call.with_roots(&[previous], |call| {
            call.table_set(globals, key, directory)?;
            let result = run(call, actor, function, params);
            // Restore the caller's directory even when a callback errors or
            // exhausts its instruction budget. This runs outside authored Lua.
            let globals_table = table(call, globals)?;
            if call.raw_table_get(globals_table, key)? != Value::Nil {
                // An existing field bypasses __newindex. Restore it without
                // entering the VM again after an exhausted instruction budget.
                call.raw_table_set(globals_table, key, previous)?;
            } else {
                call.table_set(globals, key, previous)?;
            }
            result
        })
    })
}
fn run_named(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &[u8],
    params: Option<Value>,
) -> Result<(), Error> {
    let Some((function, field)) = command(call, actor, name)? else {
        return Ok(());
    };
    let inserted = store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .active_commands
        .insert(field.clone());
    if !inserted {
        return Ok(());
    }
    // Keep the selected function alive if a callback replaces its own field or
    // forces GC. Never retain the store lock while entering authored Lua.
    let result = call.with_roots(&[function, params.unwrap_or(Value::Nil)], |call| {
        let theme = call.call(helper(call, 4)?, &[function])?[0] == Value::Boolean(true);
        match run_scoped(call, actor, function, params) {
            Err(error) if theme && error.kind() == ErrorKind::Runtime => {
                store.lock().unwrap().diagnostics.push(error.to_string());
                Ok(())
            }
            result => result,
        }
    });
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .active_commands
        .remove(&field);
    result
}
fn play(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &[u8],
    params: Option<Value>,
    recurse: bool,
) -> Result<(), Error> {
    run_named(call, store, actor, name, params)?;
    if recurse {
        for child in children(call, store, actor)? {
            play(call, store, child, name, params, true)?;
        }
    }
    Ok(())
}
fn leaves(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    action: &mut impl FnMut(&mut HostCall<'_>, TableId) -> Result<(), Error>,
) -> Result<(), Error> {
    let children = children(call, store, actor)?;
    if children.is_empty() {
        action(call, actor)?;
    } else {
        for child in children {
            leaves(call, store, child, action)?;
        }
    }
    Ok(())
}
fn release(call: &mut HostCall<'_>, store: &Shared, id: u64) -> Result<bool, Error> {
    let scene = store.lock().unwrap().scenes.remove(&id);
    let Some(scene) = scene else { return Ok(false) };
    lifecycle::invalidate_plans(call, store)?;
    // Course displays can be shared tables. A scene retires only its last
    // ownership of those actors, including their callbacks and registry roots.
    let mut retired = HashSet::new();
    {
        let mut guard = store.lock().unwrap();
        for &actor in &scene.actors {
            let other = guard
                .scenes
                .iter()
                .find_map(|(id, scene)| scene.actors.contains(&actor).then_some(*id));
            if let Some(other) = other {
                if let Some(instance) = guard.actors.get_mut(&actor)
                    && instance.scene == id
                {
                    instance.scene = other;
                }
            } else {
                retired.insert(actor);
            }
        }
    }
    store
        .lock()
        .unwrap()
        .actor_order
        .retain(|actor| !retired.contains(actor));
    let registry = table(call, call.captures()[0])?;
    for actor in scene.actors {
        if !retired.contains(&actor) {
            continue;
        }
        if !scene.sounds_retired {
            sound::retire(call, store, actor);
        }
        call.raw_table_set(registry, Value::Table(actor), Value::Nil)?;
        let mut store = store.lock().unwrap();
        store.actors.remove(&actor);
        #[cfg(feature = "test-support")]
        store.message_ranks.remove(&actor);
    }
    Ok(true)
}
fn build(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    node: TableId,
    parent: Option<TableId>,
    check_condition: bool,
    internal: bool,
) -> Result<Option<TableId>, Error> {
    let attrs = table(call, call.raw_table_get(node, Value::Number(1.0))?)?;
    if check_condition && get(call, attrs, b"Condition")? == Value::Boolean(false) {
        return Ok(None);
    }
    let template = match call.raw_table_get(node, Value::Number(3.0))? {
        Value::Table(source) => store
            .lock()
            .unwrap()
            .actors
            .get(&source)
            .map(TemplateState::from),
        _ => None,
    };
    let class = if let Some(template) = &template {
        template.state.class.as_bytes().to_vec()
    } else {
        let mut kind = get(call, attrs, b"Class")?;
        if kind == Value::Nil {
            kind = get(call, attrs, b"Type")?;
        }
        if kind == Value::Nil {
            Vec::new()
        } else {
            bytes(call, kind)?
        }
    };
    let dummy = class.is_empty();
    let class = match class.as_slice() {
        b"" | b"Actor" => "Actor",
        b"ActorFrame" => "ActorFrame",
        b"ActorFrameTexture" => "ActorFrameTexture",
        b"WrapperState" => "WrapperState",
        b"Quad" => "Quad",
        b"Sprite" => "Sprite",
        b"Banner" => "Banner",
        b"GraphDisplay" => "GraphDisplay",
        b"SongMeterDisplay" => "SongMeterDisplay",
        b"CourseContentsList" => "CourseContentsList",
        b"Model" => "Model",
        b"PlayerActor" if internal => "PlayerActor",
        b"HoldJudgment" if internal => "HoldJudgment",
        b"PercentageDisplay" if internal => "PercentageDisplay",
        b"StepsDisplay" if internal => "StepsDisplay",
        b"Timer" if internal => "Timer",
        b"NoteField" if internal => "NoteField",
        b"NoteColumnRenderer" if internal => "NoteColumnRenderer",
        b"LifeMeter" if internal => "LifeMeter",
        b"GraphDisplayBody" if internal => "GraphDisplayBody",
        b"GraphDisplayLine" if internal => "GraphDisplayLine",
        b"BitmapText" => "BitmapText",
        b"RollingNumbers" => "RollingNumbers",
        b"BPMDisplay" => "BPMDisplay",
        b"DeviceList" => "DeviceList",
        b"InputList" => "InputList",
        b"ActorMultiVertex" => "ActorMultiVertex",
        b"ActorProxy" => "ActorProxy",
        b"Sound" => "Sound",
        _ => {
            return Err(call.error(
                format!(
                    "actor class '{}' has no Rust instance implementation yet",
                    String::from_utf8_lossy(&class)
                )
                .as_bytes(),
            ));
        }
    };
    let create = helper(call, 1)?;
    let kind = call.try_intern(class.as_bytes())?;
    let empty_attrs = if dummy {
        Value::Table(call.try_new_table()?)
    } else {
        Value::Table(attrs)
    };
    let actor = call.call(
        create,
        &[
            kind,
            parent.map_or(Value::Nil, Value::Table),
            empty_attrs,
            Value::Boolean(template.is_some()),
        ],
    )?[0];
    let actor = table(call, actor)?;
    if matches!(class, "Quad" | "ActorMultiVertex") && template.is_none() {
        let key = call.try_intern(b"__songlua_default_texture")?;
        call.raw_table_set(actor, key, Value::Boolean(true))?;
    }
    let mut name = get(call, attrs, b"Name")?;
    // Constructors can name a raw CourseContentsList Display before the same
    // declaration is materialized as an ordinary child.
    if name == Value::Nil
        && let Value::Table(source) = call.raw_table_get(node, Value::Number(3.))?
    {
        name = get(call, source, b"Name")?;
        if name != Value::Nil {
            sprites::set(call, actor, "Name", name)?;
        }
    }
    let load_name = if dummy || name == Value::Nil {
        None
    } else {
        Some(bytes(call, name)?)
    };
    let registry = table(call, call.captures()[0])?;
    call.raw_table_set(registry, Value::Table(actor), Value::Boolean(true))?;
    {
        let mut store = store.lock().unwrap();
        store.scenes.get_mut(&scene).unwrap().actors.push(actor);
        store.actor_order.push(actor);
        let mut instance = Actor::new(scene, class, parent, load_name);
        if let Some(template) = &template {
            // Production clones native fields into a fresh actor at its last
            // destination. Its existing tween queue does not advance or become
            // the clone's queue; independent hibernation and immediate fields
            // are retained. Init still runs normally on the new instance.
            instance.current = template.pose;
            instance.hibernate = template.hibernate;
            instance.update_rate = template.update_rate;
            instance.propagate = template.propagate;
            instance.update_error_reported = template.update_error_reported;
            instance.state.size = template.state.size;
            instance.state.visible = template.state.visible;
            instance.state.draw_order = template.state.draw_order;
            instance.state.render = template.state.render;
            instance.state.rotation = template.state.rotation;
            instance.effects = template.effects;
        }
        store.actors.insert(actor, instance);
    }
    if class == "Sound" {
        sound::install(call, store, actor)?;
    }
    proxies::install(call, actor, class == "ActorProxy")?;
    textures::install_getter(call, store, actor)?;
    if template.is_none() {
        render::initialize(call, store, actor)?;
    }
    if class == "Model" {
        models::initialize(call, store, actor, template.is_some())?;
    }
    if text_displays::is_display(class) {
        text_displays::install(call, actor)?;
        if let Some(text) = crate::input_status_actor_text(class) {
            let value = call.try_intern(text.as_bytes())?;
            sprites::set(call, actor, "Text", value)?;
        }
    }
    if matches!(
        class,
        "GraphDisplay" | "GraphDisplayBody" | "GraphDisplayLine"
    ) {
        graphs::install(call, actor)?;
    }
    if class == "GraphDisplay" {
        graphs::initialize(call, store, scene, actor)?;
    }
    if class == "CourseContentsList" {
        courses::initialize(call, store, scene, actor)?;
    }
    if class == "SongMeterDisplay" {
        song_meters::initialize(call, store, scene, actor)?;
    }
    if class == "ActorFrameTexture" {
        framebuffers::initialize(call, actor)?;
    }
    if matches!(class, "Sprite" | "Banner") {
        sprites::initialize(call, store, actor, template.is_some())?;
    }
    if dummy {
        return Ok(Some(actor));
    }
    if matches!(
        class,
        "ActorFrame"
            | "PlayerActor"
            | "HoldJudgment"
            | "PercentageDisplay"
            | "StepsDisplay"
            | "NoteField"
            | "ActorFrameTexture"
            | "GraphDisplay"
            | "SongMeterDisplay"
            | "CourseContentsList"
            | "Model"
    ) {
        let nodes = table(call, call.raw_table_get(node, Value::Number(2.))?)?;
        let mut selected = nodes;
        let mut array_only = true;
        for i in 1..=call.raw_table_len(nodes)? {
            let entry = table(call, call.raw_table_get(nodes, Value::Number(i as f64))?)?;
            let key = call.raw_table_get(entry, Value::Number(1.))?;
            if bytes(call, key)? == b"children" {
                let node = table(call, call.raw_table_get(entry, Value::Number(2.))?)?;
                selected = table(call, call.raw_table_get(node, Value::Number(2.))?)?;
                array_only = false;
                break;
            }
        }
        for i in 1..=call.raw_table_len(selected)? {
            let entry = table(call, call.raw_table_get(selected, Value::Number(i as f64))?)?;
            let name = call.raw_table_get(entry, Value::Number(1.))?;
            let name = bytes(call, name)?;
            if array_only && (name.is_empty() || !name.iter().all(u8::is_ascii_digit)) {
                continue;
            }
            let child = table(call, call.raw_table_get(entry, Value::Number(2.))?)?;
            if let Some(child) = build(call, store, scene, child, Some(actor), true, false)? {
                store
                    .lock()
                    .unwrap()
                    .actors
                    .get_mut(&actor)
                    .unwrap()
                    .children
                    .push(child);
                let index = store.lock().unwrap().actors[&actor].children.len();
                call.raw_table_set(actor, Value::Number(index as f64), Value::Table(child))?;
            }
        }
    }
    Ok(Some(actor))
}

// Declaration construction and template cloning share scene ownership. Template
// operations do not run Init; the final materialization owns that lifecycle.
fn materialize(
    call: &mut HostCall<'_>,
    store: &Shared,
    declaration: TableId,
    init: bool,
) -> Result<u64, Error> {
    let node = call.call(helper(call, 2)?, &[Value::Table(declaration)])?[0];
    call.with_roots(&[node], |call| {
        let id = {
            let mut guard = store.lock().unwrap();
            if guard.next >= (1u64 << 53) - 1 {
                return Err(call.error(b"actor scene identity exhausted"));
            }
            guard.next += 1;
            let id = guard.next;
            guard.scenes.insert(
                id,
                Scene {
                    actors: Vec::new(),
                    root: None,
                    ended: false,
                    sounds_retired: false,
                },
            );
            id
        };
        let result =
            build(call, store, id, table(call, node)?, None, init, false).and_then(|root| {
                if init && let Some(actor) = root {
                    initialize(call, store, actor)?;
                }
                Ok(root)
            });
        match result {
            Ok(root) => {
                let mut guard = store.lock().unwrap();
                guard.scenes.get_mut(&id).unwrap().root = root;
                if !init && let Some(actor) = root {
                    let offline = !guard.clock.live.load(std::sync::atomic::Ordering::Relaxed)
                        && !guard.playback;
                    guard.actors.get_mut(&actor).unwrap().offline_template = offline;
                }
                Ok(id)
            }
            Err(error) => {
                release(call, store, id)?;
                Err(error)
            }
        }
    })
}

fn initialize(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    if !store.lock().unwrap().actors.contains_key(&actor) {
        return native_children::group_lifecycle(call, store, actor, false);
    }
    courses::prepare_raw_init(call, store, actor)?;
    if store.lock().unwrap().actors[&actor].initialized {
        return Ok(());
    }
    let original = get(call, actor, b"Name")?;
    call.with_roots(&[original], |call| {
        initialize_body(call, store, actor, original)
    })
}
fn initialize_body(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    original: Value,
) -> Result<(), Error> {
    {
        let mut store = store.lock().unwrap();
        if !store.actor_order.contains(&actor) {
            store.actor_order.push(actor);
        }
        store.actors.get_mut(&actor).unwrap().state.name.clear();
        store.actors.get_mut(&actor).unwrap().registered = true;
    }
    // The production host materializes the complete tree before Init. Every
    // child is observable while child-first Init applies names and draw order.
    for child in declared_children(store, actor) {
        native_children::adopt_declared(call, store, child, actor)?;
        initialize(call, store, child)?;
    }
    sort(call, store, actor)?;
    {
        let mut store = store.lock().unwrap();
        let actor = store.actors.get_mut(&actor).unwrap();
        if let Some(name) = actor.load_name.take() {
            actor.state.name = name;
        }
    }
    courses::publish_raw_name(call, store, actor, original)?;
    play(call, store, actor, b"Init", None, false)?;
    if let Some(stream) = song_meters::stream(call, store, actor)? {
        if store
            .lock()
            .unwrap()
            .actors
            .get(&stream)
            .is_some_and(|a| !a.initialized)
        {
            let name = get(call, stream, b"Name")?;
            if name != Value::Nil {
                let name = bytes(call, name)?;
                store
                    .lock()
                    .unwrap()
                    .actors
                    .get_mut(&stream)
                    .unwrap()
                    .load_name = Some(name);
            }
        }
        initialize(call, store, stream)?;
    }
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .initialized = true;
    courses::publish_raw_flag(call, store, actor, "__songlua_init_commands_ran")?;
    Ok(())
}
fn group(call: &mut HostCall<'_>, ids: &[TableId]) -> Result<Value, Error> {
    match ids {
        [] => Ok(Value::Nil),
        [actor] => Ok(Value::Table(*actor)),
        _ => {
            let list = call.try_new_table()?;
            for (i, id) in ids.iter().enumerate() {
                call.raw_table_set(list, Value::Number((i + 1) as f64), Value::Table(*id))?;
            }
            Ok(call.call(helper(call, 3)?, &[Value::Table(list)])?[0])
        }
    }
}
fn invoke_bound(call: &mut HostCall<'_>) -> Result<(), Error> {
    let name = *call.function_data::<&'static str>().unwrap();
    // Production's own adapters close over the receiver. Both colon and dot
    // invocation therefore address this actor, including calls with another
    // table in the receiver slot. settext uniquely always reads argument two.
    let skip = if name == "settext" {
        1
    } else {
        usize::from(matches!(call.arguments().first(), Some(Value::Table(_))))
    };
    let mut args = Vec::with_capacity(call.arguments().len() + 1);
    args.push(call.captures()[2]);
    args.extend(call.arguments().iter().skip(skip).copied());
    call.call_and_return(call.captures()[3], &args)
}

fn callback(call: &mut HostCall<'_>) -> Result<(), Error> {
    let Binding { store, op } = call.function_data::<Binding>().unwrap().clone();
    if let Op::Message(op) = op {
        return messages::callback(call, &store, op);
    }
    if matches!(op, Op::End) {
        let id = call.number(0)? as u64;
        let root = {
            let mut store = store.lock().unwrap();
            let Some(scene) = store.scenes.get_mut(&id) else {
                return call.push(Value::Boolean(false));
            };
            if scene.ended {
                return call.push(Value::Boolean(false));
            }
            // An errored End is still final. The caller observes its partial
            // effects; it must not retry callbacks or advance the outgoing tree.
            scene.ended = true;
            scene.root
        };
        if let Some(root) = root {
            lifecycle::end(call, &store, root)?;
        }
        let actors = store.lock().unwrap().scenes[&id].actors.clone();
        for actor in actors {
            sound::retire(call, &store, actor);
        }
        store
            .lock()
            .unwrap()
            .scenes
            .get_mut(&id)
            .unwrap()
            .sounds_retired = true;
        return call.push(Value::Boolean(true));
    }
    if matches!(op, Op::Start | Op::Advance | Op::DrawScene) {
        let id = call.number(0)? as u64;
        let root = store
            .lock()
            .unwrap()
            .scenes
            .get(&id)
            .map(|scene| (scene.root, scene.ended));
        let Some((root, ended)) = root else {
            return call.push(Value::Boolean(false));
        };
        if ended {
            return Err(call.error(b"cannot advance an ended song Lua scene"));
        }
        if let Some(root) = root {
            if matches!(op, Op::Start) {
                lifecycle::start(call, &store, root)?;
            } else if matches!(op, Op::DrawScene) {
                draw::scene(call, &store, root)?;
            } else {
                let delta = call.number(1)? as f32;
                lifecycle::advance(call, &store, root, delta)?;
            }
        }
        return call.push(Value::Boolean(true));
    }
    if matches!(op, Op::LoadFont) {
        return text::load_font(call, &store);
    }
    if matches!(op, Op::Template) {
        let declaration = table(call, arg(call, 0))?;
        let globals = table(call, helper(call, 5)?)?;
        for key in ["__songlua_script_dir", "__songlua_song_dir"] {
            if let Some(directory) = assets::field(call, globals, key.as_bytes())? {
                let value = call.try_intern(directory.as_bytes())?;
                sprites::set(call, declaration, key, value)?;
            }
        }
        let id = materialize(call, &store, declaration, false)?;
        let actor = store.lock().unwrap().scenes[&id]
            .root
            .expect("actor template");
        let key = call.try_intern(b"Class")?;
        call.raw_table_set(actor, key, Value::Nil)?;
        return call.push(Value::Table(actor));
    }
    if matches!(op, Op::Instantiate) {
        let declaration = table(call, arg(call, 0))?;
        let id = materialize(call, &store, declaration, true)?;
        return call.push(Value::Number(id as f64));
    }
    if matches!(op, Op::Release) {
        let id = call.number(0)? as u64;
        let removed = release(call, &store, id)?;
        return call.push(Value::Boolean(removed));
    }
    let actor = table(call, arg(call, 0))?;
    if !store.lock().unwrap().actors.contains_key(&actor) {
        return Err(call.error(b"actor instance is not owned by this runtime or has been released"));
    }
    let frame_method = matches!(
        op,
        Op::GetChildren
            | Op::GetChild
            | Op::GetNumChildren
            | Op::Sort
            | Op::OnChildren
            | Op::OnLeaves
            | Op::NamedChildren
            | Op::NamedLeaves
            | Op::Propagate
            | Op::PropagateCommand
    ) || matches!(op, Op::Render(name) if render::FRAME_METHODS.contains(&name))
        || matches!(op, Op::Draw("SetDrawFunction" | "GetDrawFunction"));
    let model_query = matches!(op, Op::GetChild | Op::GetChildren | Op::GetNumChildren)
        && store.lock().unwrap().actors[&actor].state.class == "Model";
    if frame_method && !is_frame(&store, actor) && !model_query {
        return Err(call.error(b"ActorFrame expected"));
    }
    match op {
        Op::Lifecycle(operation) => return lifecycle::method(call, &store, actor, operation),
        Op::Render(name) => return render::method(call, &store, actor, name),
        Op::Effect(name) => return effects::method(call, &store, actor, name),
        Op::Wrapper(name) => return wrappers::method(call, &store, actor, name),
        Op::Sound(name) => return sound::method(call, &store, actor, name),
        Op::Sprite(name) => return sprites::method(call, &store, actor, name),
        Op::Banner(name) => return banners::method(call, &store, actor, name),
        Op::Mesh(name) => return meshes::method(call, &store, actor, name),
        Op::CloneTemplate => {
            let id = materialize(call, &store, actor, false)?;
            let root = store.lock().unwrap().scenes[&id].root;
            return call.push(root.map_or(Value::Nil, Value::Table));
        }
        Op::Text(name) => return text::method(call, &store, actor, name),
        Op::Graph(name) => return graphs::method(call, &store, actor, name),
        Op::SongMeter(name) => return song_meters::method(call, &store, actor, name),
        Op::Course(name) => return courses::method(call, &store, actor, name),
        Op::ReadModelPaths => {
            let paths = models::paths(call, actor)?;
            store.lock().unwrap().model_paths_output = paths;
            return Ok(());
        }
        Op::ReadSongMeter => {
            let meter = song_meters::read(call, &store, actor)?;
            store.lock().unwrap().meter_output = meter;
            return Ok(());
        }
        Op::ReadGraph => {
            let graph = graphs::read(call, &store, actor)?;
            store.lock().unwrap().graph_output = Some(graph);
            return Ok(());
        }
        Op::TextDisplay(name) => return text_displays::method(call, &store, actor, name),
        Op::ReadText => {
            let output = text::read(call, actor)?;
            store.lock().unwrap().text_output = Some(output);
            return Ok(());
        }
        Op::Framebuffer(name) => return framebuffers::method(call, &store, actor, name),
        Op::ReadFramebuffer => {
            let framebuffer = framebuffers::read(call, actor)?;
            store.lock().unwrap().framebuffer_output = Some(framebuffer);
            return Ok(());
        }
        Op::Draw(name) => return draw::method(call, &store, actor, name),
        Op::ReadMesh => {
            let mesh = meshes::read(call, actor)?;
            store.lock().unwrap().mesh_output = mesh;
            return Ok(());
        }
        Op::ReadProxy => {
            let target = proxies::read(call, actor)?;
            store.lock().unwrap().proxy_output = target;
            return Ok(());
        }
        Op::GetName => {
            if store.lock().unwrap().actors[&actor].raw_instance {
                for key in [
                    b"__songlua_load_name".as_slice(),
                    b"__songlua_native_name",
                    b"Name",
                ] {
                    let value = get(call, actor, key)?;
                    if value != Value::Nil {
                        let name = assets::text(call, value)?;
                        let name = call.try_intern(name.as_bytes())?;
                        return call.push(name);
                    }
                }
            }
            let name = store.lock().unwrap().actors[&actor].state.name.clone();
            let name = call.try_intern(&name)?;
            return call.push(name);
        }
        Op::Name => {
            let name = bytes(call, arg(call, 1))?;
            if store.lock().unwrap().actors[&actor].raw_instance {
                let value = call.try_intern(&name)?;
                let key = call.try_intern(b"__songlua_load_name")?;
                if call.raw_table_get(actor, key)? != Value::Nil {
                    call.raw_table_set(actor, key, value)?;
                }
                let key = call.try_intern(b"__songlua_native_name")?;
                call.raw_table_set(actor, key, value)?;
            }
            store
                .lock()
                .unwrap()
                .actors
                .get_mut(&actor)
                .unwrap()
                .state
                .name = name;
        }
        Op::GetParent => {
            let parent = store.lock().unwrap().actors[&actor].parent;
            return call.push(parent.map_or(Value::Nil, Value::Table));
        }
        Op::GetNumChildren => {
            let count = children(call, &store, actor)?.len();
            return call.push(Value::Number(count as f64));
        }
        Op::GetChild if has_native_children(&store, actor) => {
            let key = arg(call, 1);
            let key = bytes(call, key)?;
            let map = native_children::named_children(call, actor)?;
            let value = call.with_roots(&[map], |call| {
                let key = call.try_intern(&key)?;
                call.table_get(map, key)
            })?;
            return call.push(value);
        }
        Op::GetChildren if has_native_children(&store, actor) => {
            let result = native_children::named_children(call, actor)?;
            return call.push(result);
        }
        Op::GetChild => {
            let name = bytes(call, arg(call, 1))?;
            let ids = children(call, &store, actor)?
                .into_iter()
                .filter(|id| store.lock().unwrap().actors[id].state.name == name)
                .collect::<Vec<_>>();
            let value = group(call, &ids)?;
            return call.push(value);
        }
        Op::GetChildren => {
            let result = Value::Table(call.try_new_table()?);
            return call.with_roots(&[result], |call| {
                let mut names: Vec<(Vec<u8>, Vec<TableId>)> = Vec::new();
                for id in children(call, &store, actor)? {
                    let name = store.lock().unwrap().actors[&id].state.name.clone();
                    if let Some((_, ids)) = names.iter_mut().find(|(n, _)| *n == name) {
                        ids.push(id)
                    } else {
                        names.push((name, vec![id]));
                    }
                }
                for (name, ids) in names {
                    let value = group(call, &ids)?;
                    let key = call.try_intern(&name)?;
                    call.raw_table_set(table(call, result)?, key, value)?;
                }
                call.push(result)
            });
        }
        Op::Sort => sort(call, &store, actor)?,
        Op::Propagate => {
            store
                .lock()
                .unwrap()
                .actors
                .get_mut(&actor)
                .unwrap()
                .propagate = !matches!(arg(call, 1), Value::Nil | Value::Boolean(false));
        }
        Op::AddCommand | Op::GetCommand => {
            let name = arg(call, 1);
            if matches!(op, Op::GetCommand) {
                let Some(name) = command_name(call, name) else {
                    return call.push(Value::Nil);
                };
                let value = command(call, actor, &name)?;
                return call.push(value.map_or(Value::Nil, |(function, _)| function));
            }
            let name = bytes(call, name)?;
            std::str::from_utf8(&name).map_err(|_| call.error(b"command name must be UTF-8"))?;
            let value = arg(call, 2);
            if !matches!(value, Value::Function(_) | Value::Native(_)) {
                return Err(call.error(b"function expected"));
            }
            let key = call.try_intern(&[name.as_slice(), b"Command"].concat())?;
            call.table_set(Value::Table(actor), key, value)?;
        }
        Op::PlayCommand | Op::PropagateCommand | Op::NamedChildren | Op::NamedLeaves => {
            let Some(name) = command_name(call, arg(call, 1)) else {
                return call.push(Value::Table(actor));
            };
            let params = call.arguments().get(2).copied();
            match op {
                Op::NamedLeaves => leaves(call, &store, actor, &mut |call, actor| {
                    run_named(call, &store, actor, &name, params)
                })?,
                Op::NamedChildren | Op::PropagateCommand => {
                    for child in children(call, &store, actor)? {
                        play(
                            call,
                            &store,
                            child,
                            &name,
                            params,
                            matches!(op, Op::PropagateCommand),
                        )?;
                    }
                }
                _ => {
                    let propagate = store.lock().unwrap().actors[&actor].propagate;
                    if !propagate {
                        run_named(call, &store, actor, &name, params)?;
                    }
                    for child in children(call, &store, actor)? {
                        play(call, &store, child, &name, params, true)?;
                    }
                }
            }
        }
        Op::Recursive => {
            // The existing production class exposes this name but has no
            // semantic implementation. Migration must preserve that error.
            return Err(call.error(
                b"native actor method RunCommandsRecursively has no semantic implementation",
            ));
        }
        Op::OnChildren | Op::OnLeaves => {
            let function = arg(call, 1);
            if matches!(function, Value::Function(_) | Value::Native(_)) {
                let params = call.arguments().get(2).copied();
                match op {
                    Op::OnLeaves => leaves(call, &store, actor, &mut |call, actor| {
                        run(call, actor, function, None)
                    })?,
                    _ => {
                        for child in children(call, &store, actor)? {
                            run(call, child, function, params)?;
                        }
                    }
                }
            }
        }
        Op::Set(name) => set_scalar(call, &store, actor, name)?,
        Op::Get(name) => return get_scalar(call, &store, actor, name),
        Op::Instantiate
        | Op::Template
        | Op::LoadFont
        | Op::Release
        | Op::Start
        | Op::Advance
        | Op::End
        | Op::DrawScene
        | Op::Message(_) => {
            unreachable!()
        }
    }
    call.push(Value::Table(actor))
}
fn command_name(call: &HostCall<'_>, value: Value) -> Option<Vec<u8>> {
    let Value::String(id) = value else {
        return None;
    };
    std::str::from_utf8(call.string_bytes(id)?)
        .ok()
        .map(|name| name.as_bytes().to_vec())
}
fn set_scalar(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    if name == "draworder" {
        if let Some(value) = integer_scalar(call, arg(call, 1)) {
            store
                .lock()
                .unwrap()
                .actors
                .get_mut(&actor)
                .unwrap()
                .state
                .draw_order = value;
        }
        return Ok(());
    }
    let allows_nonfinite = matches!(
        name,
        "x" | "y" | "zoom" | "zoomx" | "zoomy" | "zoomz" | "rotationx" | "rotationy" | "rotationz"
    );
    if name == "xy" {
        let x = float_scalar(call, arg(call, 1), false);
        let y = float_scalar(call, arg(call, 2), false);
        let mut store = store.lock().unwrap();
        let position = store.actors.get_mut(&actor).unwrap().destination_mut();
        if let Some(x) = x {
            position.x = x;
        }
        if let Some(y) = y {
            position.y = y;
        }
        return Ok(());
    }
    let first = if name == "visible" {
        let Some(value) = boolish(call, arg(call, 1)) else {
            return Ok(());
        };
        value as u8 as f32
    } else {
        let Some(value) = float_scalar(call, arg(call, 1), allows_nonfinite) else {
            return Ok(());
        };
        value
    };
    let second = if name == "setsize" {
        let Some(value) = float_scalar(call, arg(call, 2), false) else {
            return Ok(());
        };
        value
    } else {
        0.
    };
    if matches!(name, "SetWidth" | "SetHeight") {
        sprites::refresh_size(call, store, actor)?;
    }
    if matches!(name, "SetWidth" | "SetHeight" | "setsize") {
        let size = {
            let store = store.lock().unwrap();
            let actor = &store.actors[&actor];
            (actor.state.class == "ActorFrameTexture").then(|| match name {
                "SetWidth" => [first, actor.state.size[1].abs()],
                "SetHeight" => [actor.state.size[0].abs(), first],
                _ => [first, second],
            })
        };
        if let Some(size) = size {
            let value = sprites::vector_value(call, &size)?;
            let key = call.try_intern(b"__songlua_state_size")?;
            call.raw_table_set(actor, key, value)?;
        }
    }
    if name == "visible" {
        sprites::set(
            call,
            actor,
            "__songlua_visible",
            Value::Boolean(first != 0.),
        )?;
    }
    let captured_position =
        if !store.lock().unwrap().playback && matches!(name, "addx" | "addy" | "addz") {
            text::captured_position(call, actor, &name[3..])?
        } else {
            None
        };
    let id = actor;
    let mut guard = store.lock().unwrap();
    let actor = guard.actors.get_mut(&id).unwrap();
    let immediate = &mut actor.state;
    match name {
        "SetWidth" => immediate.size = [first, immediate.size[1].abs()],
        "SetHeight" => immediate.size = [immediate.size[0].abs(), first],
        "setsize" => immediate.size = [first, second],
        "visible" => immediate.visible = first != 0.,
        _ => {}
    }
    if matches!(name, "SetWidth" | "SetHeight" | "setsize") {
        immediate.render.size = Some(immediate.size);
    }
    let s = actor.destination_mut();
    match name {
        "x" => s.x = first,
        "y" => s.y = first,
        "z" => s.z = first,
        "addx" => s.x = captured_position.unwrap_or(s.x) + first,
        "addy" => s.y = captured_position.unwrap_or(s.y) + first,
        "addz" => s.z = captured_position.unwrap_or(s.z) + first,
        "zoom" => {
            s.zoom = first;
            s.zoom_x = first;
            s.zoom_y = first;
            s.zoom_z = first;
        }
        "zoomx" => s.zoom_x = first,
        "zoomy" => s.zoom_y = first,
        "zoomz" => s.zoom_z = first,
        "rotationx" => s.rot_x_deg = first,
        "rotationy" => s.rot_y_deg = first,
        "rotationz" => s.rot_z_deg = first,
        "addrotationx" => s.rot_x_deg += first,
        "addrotationy" => s.rot_y_deg += first,
        "addrotationz" => s.rot_z_deg += first,
        "aux" => s.aux = first,
        "SetWidth" | "SetHeight" | "setsize" | "visible" => {}
        _ => unreachable!(),
    }
    match name {
        "rotationx" | "addrotationx" => actor.state.rotation[0] = actor.destination().rot_x_deg,
        "rotationy" | "addrotationy" => actor.state.rotation[1] = actor.destination().rot_y_deg,
        "rotationz" | "addrotationz" => actor.state.rotation[2] = actor.destination().rot_z_deg,
        _ => {}
    }
    let template_position = if actor.offline_template {
        match name {
            "x" | "addx" => Some(("x", actor.destination().x)),
            "y" | "addy" => Some(("y", actor.destination().y)),
            "z" | "addz" => Some(("z", actor.destination().z)),
            _ => None,
        }
    } else {
        None
    };
    drop(guard);
    if let Some((axis, value)) = template_position {
        text::capture_template_position(call, id, axis, value)?;
    }
    if matches!(name, "zoom" | "zoomx" | "zoomy") {
        text::pre_zoom(call, store, id, name != "zoomy", name != "zoomx")?;
    }
    Ok(())
}
fn float_scalar(call: &HostCall<'_>, value: Value, allows_nonfinite: bool) -> Option<f32> {
    match value {
        Value::Number(value) => {
            let value = value as f32;
            (allows_nonfinite || value.is_finite()).then_some(value)
        }
        Value::String(id) => std::str::from_utf8(call.string_bytes(id)?)
            .ok()?
            .trim()
            .parse()
            .ok(),
        _ => None,
    }
}
fn integer_scalar(call: &HostCall<'_>, value: Value) -> Option<i32> {
    match value {
        Value::Number(value) if value.is_finite() => Some(value.round() as i32),
        Value::String(id) => {
            let text = std::str::from_utf8(call.string_bytes(id)?).ok()?.trim();
            text.parse()
                .ok()
                .or_else(|| text.parse::<f32>().ok().map(|value| value.round() as i32))
        }
        _ => None,
    }
}
fn boolish(call: &HostCall<'_>, value: Value) -> Option<bool> {
    match value {
        Value::Boolean(value) => Some(value),
        Value::Number(value) => Some(value != 0.0),
        Value::String(id) => {
            let text = std::str::from_utf8(call.string_bytes(id)?).ok()?.trim();
            if ["true", "yes", "on"]
                .iter()
                .any(|word| text.eq_ignore_ascii_case(word))
            {
                Some(true)
            } else if ["false", "no", "off"]
                .iter()
                .any(|word| text.eq_ignore_ascii_case(word))
            {
                Some(false)
            } else {
                text.parse::<f32>().ok().map(|value| value != 0.0)
            }
        }
        _ => None,
    }
}
fn get_scalar(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    if matches!(
        name,
        "GetWidth" | "GetHeight" | "GetZoomedWidth" | "GetZoomedHeight"
    ) {
        sprites::refresh_size(call, store, actor)?;
    }
    let store = store.lock().unwrap();
    let actor = &store.actors[&actor];
    let s = &actor.state;
    let current = &actor.current;
    let dest = actor.destination();
    let value = match name {
        "GetX" => current.x,
        "GetY" => current.y,
        "GetZ" => current.z,
        "GetDestX" => dest.x,
        "GetDestY" => dest.y,
        "GetDestZ" => dest.z,
        "GetZoom" | "GetZoomX" => dest.zoom_x,
        "GetZoomY" => dest.zoom_y,
        "GetZoomZ" => dest.zoom_z,
        "GetRotationX" => s.rotation[0],
        "GetRotationY" => s.rotation[1],
        "GetRotationZ" => s.rotation[2],
        "GetWidth" => s.size[0].abs(),
        "GetHeight" => s.size[1].abs(),
        "GetZoomedWidth" => s.size[0].abs() * (s.render.basezoom_x * dest.zoom_x),
        "GetZoomedHeight" => s.size[1].abs() * (s.render.basezoom_y * dest.zoom_y),
        "getaux" => current.aux,
        "GetVisible" => return call.push(Value::Boolean(s.visible)),
        _ => unreachable!(),
    };
    call.push(Value::Number(f64::from(value)))
}

//! Existing actor queue and frame lifecycle, owned by the song host.
use super::*;

pub(super) struct TweenStep {
    duration: f32,
    left: f32,
    from: Option<TweenPose>,
    pub(super) to: TweenPose,
    easing: String,
    command: Option<Vec<u8>>,
}

#[derive(Clone, Copy)]
pub(super) enum Lifecycle {
    Ease(&'static str),
    Tween,
    Sleep,
    Hibernate,
    Stop,
    Finish,
    Hurry,
    TimeLeft,
    Queue,
    QueueMessage,
    Update,
    Rate,
    GetRate,
}

pub(super) const ACTOR_METHODS: &[(&str, Lifecycle)] = &[
    ("linear", Lifecycle::Ease("linear")),
    ("accelerate", Lifecycle::Ease("inQuad")),
    ("decelerate", Lifecycle::Ease("outQuad")),
    ("smooth", Lifecycle::Ease("smooth")),
    ("spring", Lifecycle::Ease("spring")),
    ("bouncebegin", Lifecycle::Ease("bouncebegin")),
    ("bounceend", Lifecycle::Ease("bounceend")),
    ("tween", Lifecycle::Tween),
    ("sleep", Lifecycle::Sleep),
    ("hibernate", Lifecycle::Hibernate),
    ("stoptweening", Lifecycle::Stop),
    ("finishtweening", Lifecycle::Finish),
    ("hurrytweening", Lifecycle::Hurry),
    ("GetTweenTimeLeft", Lifecycle::TimeLeft),
    ("queuecommand", Lifecycle::Queue),
    ("queuemessage", Lifecycle::QueueMessage),
];
pub(super) const FRAME_METHODS: &[(&str, Lifecycle)] = &[
    ("SetUpdateFunction", Lifecycle::Update),
    ("SetUpdateRate", Lifecycle::Rate),
    ("GetUpdateRate", Lifecycle::GetRate),
];

fn finish(call: &mut HostCall<'_>, store: &Shared, id: TableId) -> Result<(), Error> {
    {
        let mut store = store.lock().unwrap();
        let actor = store.actors.get_mut(&id).unwrap();
        if let Some(last) = actor.queue.back() {
            actor.current = last.to;
        }
        actor.queue.clear();
        actor.sync_rotation_getters();
    }
    // Finish also visits native named children. Hurry, TimeLeft and ordinary
    // frame updates retain the production traversal of authored children only.
    for child in children(call, store, id)? {
        finish(call, store, child)?;
    }
    Ok(())
}

fn hurry(store: &mut Store, id: TableId, factor: f32) {
    let actor = store.actors.get_mut(&id).unwrap();
    for step in &mut actor.queue {
        step.duration *= factor;
        step.left *= factor;
    }
    for child in actor.children.clone() {
        hurry(store, child, factor);
    }
}

fn time_left(store: &Store, id: TableId) -> f32 {
    let actor = &store.actors[&id];
    let mut left = actor
        .queue
        .iter()
        .fold(actor.hibernate, |left, step| left + step.left);
    for &child in &actor.children {
        let child = actor.hibernate + time_left(store, child);
        if left < child {
            left = child;
        }
    }
    left
}

fn queue(
    call: &mut HostCall<'_>,
    store: &Shared,
    id: TableId,
    duration: f32,
    easing: &str,
    command: Option<Vec<u8>>,
) -> Result<(), Error> {
    // BeginTweening finishes the actor subtree before adding its 52nd state.
    if store.lock().unwrap().actors[&id].queue.len() > 50 {
        finish(call, store, id)?;
    }
    let mut store = store.lock().unwrap();
    let actor = store.actors.get_mut(&id).unwrap();
    let to = *actor.destination();
    actor.queue.push_back(TweenStep {
        duration,
        left: duration,
        from: None,
        to,
        easing: easing.to_owned(),
        command,
    });
    Ok(())
}

fn duration(call: &HostCall<'_>, value: Value, sleep: bool) -> f32 {
    // The production numeric helpers parse string durations as Rust floats,
    // but reject nonfinite numeric values (Sleep retains positive infinity).
    let value = match value {
        Value::Number(value) if value.is_finite() || (sleep && value == f64::INFINITY) => {
            Some(value)
        }
        Value::String(id) => call
            .string_bytes(id)
            .and_then(|text| std::str::from_utf8(text).ok())
            .and_then(|text| text.trim().parse::<f64>().ok()),
        _ => None,
    };
    value.unwrap_or(0.0).max(0.0) as f32
}

fn native_tween(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    let duration = call.number(1)? as f32;
    if duration < 0.0 {
        return Ok(());
    }
    if duration.is_nan() {
        return Err(call.error(b"invalid tween duration"));
    }
    let names = [
        "TweenType_Linear",
        "TweenType_Accelerate",
        "TweenType_Decelerate",
        "TweenType_Spring",
        "TweenType_Bezier",
    ];
    let kind = match arg(call, 2) {
        Value::Number(index) if (0.0..5.0).contains(&index) && index.fract() == 0.0 => {
            Some(index as usize)
        }
        Value::String(id) => call
            .string_bytes(id)
            .and_then(|name| std::str::from_utf8(name).ok())
            .and_then(|name| {
                names.iter().position(|full| {
                    name == *full || name.eq_ignore_ascii_case(full.split_once('_').unwrap().1)
                })
            }),
        _ => None,
    }
    .ok_or_else(|| call.error(b"Expected TweenType"))?;
    let easing = if kind == 4 {
        let controls = table(call, arg(call, 3))?;
        let count = call.raw_table_len(controls)?;
        if count != 4 && count != 8 {
            return Ok(());
        }
        let mut points = Vec::with_capacity(count);
        for index in 1..=count {
            let value = call.raw_table_get(controls, Value::Number(index as f64))?;
            let value = call.call(helper(call, 6)?, &[value])?[0];
            let value = if let Value::Number(value) = value {
                value as f32
            } else {
                0.0
            };
            points.push(value.to_string());
        }
        format!("bezier({})", points.join(","))
    } else {
        ["linear", "inQuad", "outQuad", "spring"][kind].to_owned()
    };
    queue(call, store, actor, duration, &easing, None)
}

pub(super) fn method(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    op: Lifecycle,
) -> Result<(), Error> {
    if matches!(op, Lifecycle::Update | Lifecycle::Rate | Lifecycle::GetRate)
        && !is_frame(store, actor)
    {
        return Err(call.error(b"ActorFrame expected"));
    }
    match op {
        Lifecycle::Ease(easing) => {
            let duration = duration(call, arg(call, 1), false);
            queue(call, store, actor, duration, easing, None)?;
        }
        Lifecycle::Tween => native_tween(call, store, actor)?,
        Lifecycle::Sleep => {
            let duration = duration(call, arg(call, 1), true);
            queue(call, store, actor, duration, "linear", None)?;
            queue(call, store, actor, 0.0, "linear", None)?;
        }
        Lifecycle::Hibernate => {
            let duration = float_scalar(call, arg(call, 1), true).unwrap_or(0.0);
            store
                .lock()
                .unwrap()
                .actors
                .get_mut(&actor)
                .unwrap()
                .hibernate = duration;
        }
        Lifecycle::Stop => {
            let mut store = store.lock().unwrap();
            let actor = store.actors.get_mut(&actor).unwrap();
            actor.queue.clear();
            actor.sync_rotation_getters();
        }
        Lifecycle::Finish => finish(call, store, actor)?,
        Lifecycle::Hurry => {
            let factor = call.number(1)? as f32;
            if factor < 0.0 {
                return Err(call.error(b"hurrytweening factor must not be negative"));
            }
            hurry(&mut store.lock().unwrap(), actor, factor);
        }
        Lifecycle::TimeLeft => {
            return call.push(Value::Number(
                time_left(&store.lock().unwrap(), actor) as f64
            ));
        }
        Lifecycle::Queue | Lifecycle::QueueMessage => {
            if let Some(mut name) = command_name(call, arg(call, 1)) {
                if matches!(op, Lifecycle::QueueMessage) {
                    name.insert(0, b'!');
                }
                queue(call, store, actor, 0.0, "linear", Some(name))?;
            }
        }
        Lifecycle::Update => {
            let function = arg(call, 1);
            if !matches!(function, Value::Nil | Value::Function(_) | Value::Native(_)) {
                return Err(call.error(b"SetUpdateFunction requires a function or nil"));
            }
            let key = call.try_intern(b"__songlua_update_function")?;
            call.table_set(Value::Table(actor), key, function)?;
            invalidate_plans(call, store)?;
        }
        Lifecycle::Rate => {
            let rate = call.number(1)? as f32;
            if rate <= 0.0 {
                return Err(call.error(b"Update rate must be greater than 0"));
            }
            if rate > 0.0 {
                store
                    .lock()
                    .unwrap()
                    .actors
                    .get_mut(&actor)
                    .unwrap()
                    .update_rate = rate;
                invalidate_plans(call, store)?;
            }
        }
        Lifecycle::GetRate => {
            return call.push(Value::Number(
                store.lock().unwrap().actors[&actor].update_rate as f64,
            ));
        }
    }
    call.push(Value::Table(actor))
}

pub(super) fn start(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    if store.lock().unwrap().actors[&actor].started {
        return Ok(());
    }
    play(call, store, actor, b"Begin", None, true)?;
    startup(call, store, actor)
}

pub(super) fn end(call: &mut HostCall<'_>, store: &Shared, root: TableId) -> Result<(), Error> {
    let globals = table(call, helper(call, 5)?)?;
    let key = call.try_intern(b"__songlua_top_screen")?;
    call.raw_table_set(globals, key, Value::Nil)?;
    // The production live scene owns a synthetic root. End walks its ordinary
    // descendants in their current order, excluding that root and wrappers.
    // Commands may append tweens/queues, but End never advances them.
    for child in children(call, store, root)? {
        play(call, store, child, b"End", None, true)?;
    }
    Ok(())
}

pub(super) fn startup(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<(), Error> {
    if !store.lock().unwrap().actors.contains_key(&actor) {
        return native_children::group_lifecycle(call, store, actor, true);
    }
    if store.lock().unwrap().actors[&actor].started {
        return Ok(());
    }
    run_named(call, store, actor, b"On", None)?;
    for child in declared_children(store, actor) {
        native_children::adopt_declared(call, store, child, actor)?;
        startup(call, store, child)?;
    }
    if let Some(stream) = song_meters::stream(call, store, actor)? {
        startup(call, store, stream)?;
    }
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .started = true;
    courses::publish_raw_flag(call, store, actor, "__songlua_startup_commands_ran")?;
    Ok(())
}

fn advance_queue(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    mut remaining: f32,
) -> Result<(), Error> {
    // A meter stream hidden by an already initialized duplicate-name group
    // has never subscribed. Its stored queue/getters remain observable, but
    // production does not advance that queue without native registration.
    if !store.lock().unwrap().actors[&actor].registered {
        return Ok(());
    }
    let mut dispatched = 0;
    // Commands can replace the queue. Release metadata before entering Lua and
    // consume the original frame's remaining native float time afterwards.
    while remaining > 0.0 {
        let command = {
            let mut store = store.lock().unwrap();
            let sync = !store.clock.live.load(std::sync::atomic::Ordering::Relaxed);
            let actor = store.actors.get_mut(&actor).unwrap();
            let Some(step) = actor.queue.front_mut() else {
                break;
            };
            let beginning = step.from.is_none();
            if beginning {
                step.from = Some(actor.current);
            }
            let command = if beginning { step.command.take() } else { None };
            let used = remaining.min(step.left);
            step.left -= used;
            remaining -= used;
            if step.left == 0.0 {
                actor.current = step.to;
                actor.queue.pop_front();
            } else {
                let factor = crate::overlay_command_ease_factor(
                    Some(&step.easing),
                    1.0 - step.left / step.duration,
                    None,
                );
                actor.current = step.from.unwrap().lerp(step.to, factor);
            }
            if sync {
                actor.sync_rotation_getters();
            }
            command
        };
        if let Some(command) = command {
            dispatched += 1;
            if dispatched > 10000 {
                return Err(call.error(b"nonterminating zero-time actor command queue"));
            }
            if let Some(message) = command.strip_prefix(b"!") {
                messages::queued(call, store, message)?;
            } else {
                play(call, store, actor, &command, None, true)?;
            }
        }
    }
    Ok(())
}

pub(super) struct FrameNode {
    actor: TableId,
    owned: bool,
    wrappers: Vec<FrameNode>,
    children: Vec<FrameNode>,
    columns: Vec<FrameNode>,
}
pub(super) struct Plan {
    roots: TableId,
    node: FrameNode,
}
pub(super) fn invalidate_plans(call: &mut HostCall<'_>, store: &Shared) -> Result<(), Error> {
    let plans = std::mem::take(&mut store.lock().unwrap().update_plans);
    let registry = table(call, call.captures()[0])?;
    for plan in plans.into_values() {
        call.raw_table_set(registry, Value::Table(plan.roots), Value::Nil)?;
    }
    Ok(())
}
fn plan(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    roots: TableId,
) -> Result<FrameNode, Error> {
    call.with_roots(&[Value::Table(actor)], |call| {
        let owned = store.lock().unwrap().actors.contains_key(&actor);
        let (wrappers, children) = if owned {
            let store = store.lock().unwrap();
            let node = &store.actors[&actor];
            (node.wrappers.clone(), node.children.clone())
        } else {
            // Generated duplicate-name groups have no raw native pose or queue.
            // The cached traversal still owns their table and visits their array.
            call.raw_table_set(roots, Value::Table(actor), Value::Boolean(true))?;
            (Vec::new(), native_children::group_members(call, actor)?)
        };
        let wrappers = wrappers
            .into_iter()
            .map(|id| plan(call, store, id, roots))
            .collect::<Result<_, _>>()?;
        let mut nodes = Vec::new();
        for child in children {
            native_children::adopt_declared(call, store, child, actor)?;
            nodes.push(plan(call, store, child, roots)?);
        }
        if owned && let Some(stream) = song_meters::stream(call, store, actor)? {
            nodes.push(plan(call, store, stream, roots)?);
        }
        let mut columns = Vec::new();
        for column in notefields::update_columns(call, actor)? {
            columns.push(plan(call, store, column, roots)?);
        }
        Ok(FrameNode {
            actor,
            owned,
            wrappers,
            children: nodes,
            columns,
        })
    })
}

pub(super) fn advance(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    delta: f32,
) -> Result<(), Error> {
    // Production retains its traversal until an invalidating operation such as
    // SetUpdateFunction/SetUpdateRate. SortByDrawOrder alone does not invalidate
    // it. The current frame keeps its original plan even across invalidation;
    // callback values themselves are still resolved at the time of invocation.
    let cached = store.lock().unwrap().update_plans.get(&actor).cloned();
    let plan = if let Some(plan) = cached {
        plan
    } else {
        let roots = call.try_new_table()?;
        let plan = call.with_roots(&[Value::Table(roots)], |call| {
            let node = plan(call, store, actor, roots)?;
            let registry = table(call, call.captures()[0])?;
            call.raw_table_set(registry, Value::Table(roots), Value::Boolean(true))?;
            Ok(Arc::new(Plan { roots, node }))
        })?;
        store
            .lock()
            .unwrap()
            .update_plans
            .insert(actor, plan.clone());
        plan
    };
    // An authored callback may invalidate the cache and collect while this
    // frame still uses the original plan's proxy groups.
    call.with_roots(&[Value::Table(plan.roots)], |call| {
        advance_node(call, store, &plan.node, delta)
    })
}

fn advance_node(
    call: &mut HostCall<'_>,
    store: &Shared,
    node: &FrameNode,
    delta: f32,
) -> Result<(), Error> {
    let actor = node.actor;
    let material_delta = delta;
    let delta = if !node.owned {
        delta
    } else {
        let mut guard = store.lock().unwrap();
        let actor = guard.actors.get_mut(&actor).unwrap();
        if actor.hibernate > 0.0 {
            let left = actor.hibernate - delta;
            actor.hibernate = left.max(0.0);
            if left <= 0.0 {
                -left
            } else {
                drop(guard);
                models::advance_materials(store, node.actor, material_delta);
                for column in &node.columns {
                    advance_node(call, store, column, material_delta)?;
                }
                return Ok(());
            }
        } else {
            delta
        }
    };
    // Wrappers receive the owner's post-hibernation delta before its update
    // rate. Their callbacks can change that rate for this same frame.
    for wrapper in &node.wrappers {
        advance_node(call, store, wrapper, delta)?;
    }
    let delta = if node.owned {
        let delta = delta * store.lock().unwrap().actors[&actor].update_rate;
        effects::advance(call, store, actor, delta)?;
        advance_queue(call, store, actor, delta)?;
        delta
    } else {
        delta
    };
    for child in &node.children {
        advance_node(call, store, child, delta)?;
    }
    models::advance_materials(store, actor, material_delta);
    let function = get(call, actor, b"__songlua_update_function")?;
    if function != Value::Nil {
        if !matches!(function, Value::Function(_) | Value::Native(_)) {
            return Err(call.error(b"actor update function must be a function"));
        }
        let result = call.with_roots(&[function], |call| {
            run_scoped(call, actor, function, Some(Value::Number(delta as f64)))
        });
        match result {
            Err(error) if error.kind() == ErrorKind::Runtime => {
                let mut store = store.lock().unwrap();
                if let Some(actor) = store.actors.get_mut(&actor) {
                    if !actor.update_error_reported {
                        actor.update_error_reported = true;
                        store.diagnostics.push(error.to_string());
                    }
                } else {
                    store.diagnostics.push(error.to_string());
                }
            }
            result => result?,
        }
    }
    // NoteField advances its column vector after its frame callback, using the
    // incoming delta outside the frame's hibernation and update-rate gates.
    for column in &node.columns {
        advance_node(call, store, column, material_delta)?;
    }
    Ok(())
}

//! Generated ScreenGameplay display children, before screen ownership/On commands.
use super::*;
use generated_players::dummy;
use sprites::{field, set};

struct Build {
    store: Shared,
    name: String,
}

const LYRIC_COMMANDS: &[u8] = br#"return function()
return {
    Back = function(self) self:LyricCommand('Back') end,
    Front = function(self) self:LyricCommand('Front') end,
    SetNoReverseCommand = function(self) self:x(SCREEN_CENTER_X):y(SCREEN_CENTER_Y + 160) end,
    SetReverseCommand = function(self) self:x(SCREEN_CENTER_X):y(SCREEN_CENTER_Y - 140) end,
    SetOneReverseCommand = function(self) self:x(SCREEN_CENTER_X):y(SCREEN_CENTER_Y - 205) end,
}
end"#;
const LYRIC_INITIAL: &[u8] = br#"return function()
local allReverse, anyReverse = true, false
for _, player in ipairs(GAMESTATE:GetEnabledPlayers()) do
    local reverse = GAMESTATE:GetPlayerState(player):GetPlayerOptions('ModsLevel_Current'):Reverse() == 1
    allReverse = allReverse and reverse
    anyReverse = anyReverse or reverse
end
return allReverse and 'SetReverse' or anyReverse and 'SetOneReverse' or 'SetNoReverse'
end"#;

impl Actors {
    pub(in crate::rust_engine) fn screen_part(
        &self,
        vm: &mut Vm,
        name: &str,
    ) -> Result<ActorScene, Error> {
        ensure_helpers(vm, self.helpers)?;
        let function = vm.new_host_function_with_data(
            construct,
            &[Value::Table(self.registry), Value::Table(self.helpers)],
            Build {
                store: self.store.clone(),
                name: name.to_owned(),
            },
        )?;
        let Value::Number(id) = vm.call(function, &[])?[0] else {
            unreachable!()
        };
        Ok(ActorScene {
            owner: self.registry,
            id: id as u64,
        })
    }
}

pub(super) fn ensure_helpers(vm: &mut Vm, helpers: TableId) -> Result<(), Error> {
    steps_displays::ensure_helpers(vm, helpers)?;
    for (key, source, name) in [
        (
            "lyric_commands",
            LYRIC_COMMANDS,
            b"@theme:/metrics.ini:LyricDisplay".as_slice(),
        ),
        (
            "lyric_initial",
            LYRIC_INITIAL,
            b"@theme:/ScreenGameplay:LyricDisplayPosition".as_slice(),
        ),
    ] {
        let value = vm.try_intern(key.as_bytes())?;
        if vm.raw_table_get(helpers, value)? == Value::Nil {
            let code = compile_named(source, name)?;
            let function = vm.execute(&code)?[0];
            super::super::put(vm, helpers, key, function)?;
        }
    }
    Ok(())
}

fn construct(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Build>().unwrap();
    let store = data.store.clone();
    let name = data.name.clone();
    let id = {
        let mut guard = store.lock().unwrap();
        if guard.next >= (1u64 << 53) - 1 {
            return Err(call.error(b"actor scene identity exhausted"));
        }
        guard.next += 1;
        let id = guard.next;
        guard.scenes.insert(
            id,
            Scene {
                actors: Vec::new(),
                root: None,
                ended: false,
                sounds_retired: false,
            },
        );
        id
    };
    match create(call, &store, id, &name) {
        Ok(actor) => store.lock().unwrap().scenes.get_mut(&id).unwrap().root = Some(actor),
        Err(error) => {
            release(call, &store, id)?;
            return Err(error);
        }
    }
    call.push(Value::Number(id as f64))
}

pub(super) fn create(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    name: &str,
) -> Result<TableId, Error> {
    if name.eq_ignore_ascii_case("Timer") {
        let actor = dummy(call, store, scene, "Timer", name, None)?;
        let function = call.new_host_function(timer_seconds, &[])?;
        let bound = get(call, actor, b"__songlua_bound_methods")?;
        set(call, table(call, bound)?, "GetSeconds", function)?;
        return Ok(actor);
    }
    if let Some(index) = crate::top_screen_score_index(name) {
        return score(call, store, scene, index);
    }
    if crate::top_screen_steps_display_index(name).is_some() {
        return steps_displays::create(call, store, scene, name);
    }
    if name.eq_ignore_ascii_case("LyricDisplay") {
        return lyrics(call, store, scene, name);
    }
    if name.eq_ignore_ascii_case("SongBackground") {
        return background(call, store, scene);
    }
    if name.eq_ignore_ascii_case("Debug") {
        let actor = text(call, store, scene, name, "")?;
        let globals = table(call, helper(call, 5)?)?;
        let center = field(call, globals, "SCREEN_CENTER_X")?;
        let center = number(call, center)?;
        let bottom = field(call, globals, "SCREEN_BOTTOM")?;
        let bottom = number(call, bottom)?;
        for (method, value) in [("x", center), ("y", bottom - 116.), ("zoom", 0.75)] {
            invoke(call, actor, method, &[Value::Number(value as f64)])?;
        }
        return Ok(actor);
    }
    if ["Overlay", "Header", "Footer", "SongForeground"]
        .iter()
        .any(|part| name.eq_ignore_ascii_case(part))
    {
        return dummy(call, store, scene, "ActorFrame", name, None);
    }
    if ["StepsDescription", "PlayerOptions", "ActiveAttackList"]
        .iter()
        .any(|prefix| name.starts_with(prefix))
        || name == "SongOptions"
    {
        let actor = text(call, store, scene, name, "")?;
        invoke(call, actor, "visible", &[Value::Boolean(false)])?;
        return Ok(actor);
    }
    if name.starts_with("OniGameOver") {
        let actor = dummy(call, store, scene, "Sprite", name, None)?;
        blank_texture(call, store, actor)?;
        return Ok(actor);
    }
    Err(call.error(b"screen part is not implemented"))
}

fn timer_seconds(call: &mut HostCall<'_>) -> Result<(), Error> {
    call.push(Value::Number(0.))
}

fn text(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    name: &str,
    value: &str,
) -> Result<TableId, Error> {
    let actor = dummy(call, store, scene, "BitmapText", name, None)?;
    let value = call.try_intern(value.as_bytes())?;
    set(call, actor, "Text", value)?;
    Ok(actor)
}

pub(super) fn blank_texture(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<(), Error> {
    let path =
        crate::blank_texture::load_native_blank_texture().map_err(|e| call.error(e.as_bytes()))?;
    let path = call.try_intern(path.as_bytes())?;
    sprites::set_texture(call, store, actor, path, false)
}

pub(super) fn append(
    call: &mut HostCall<'_>,
    store: &Shared,
    parent: TableId,
    child: TableId,
) -> Result<(), Error> {
    native_children::adopt(call, store, child, parent)?;
    call.raw_table_set(
        parent,
        Value::Number((call.raw_table_len(parent)? + 1) as f64),
        Value::Table(child),
    )?;
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&parent)
        .unwrap()
        .children
        .push(child);
    Ok(())
}

pub(super) fn named(
    call: &mut HostCall<'_>,
    store: &Shared,
    parent: TableId,
    name: &str,
    child: TableId,
) -> Result<(), Error> {
    native_children::adopt(call, store, child, parent)?;
    native_children::insert(call, parent, name, Value::Table(child))
}

fn score(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    index: usize,
) -> Result<TableId, Error> {
    let actor = dummy(
        call,
        store,
        scene,
        "ActorFrame",
        crate::top_screen_score_name(index),
        None,
    )?;
    let frame = dummy(call, store, scene, "Sprite", "", None)?;
    blank_texture(call, store, frame)?;
    named(call, store, actor, "", frame)?;
    let percent = dummy(
        call,
        store,
        scene,
        "PercentageDisplay",
        "ScoreDisplayPercentage Percent",
        None,
    )?;
    let name = crate::top_screen_score_percent_name(index);
    let text = text(call, store, scene, name, "0.00%")?;
    named(call, store, percent, name, text)?;
    named(
        call,
        store,
        actor,
        "ScoreDisplayPercentage Percent",
        percent,
    )?;
    Ok(actor)
}

fn invoke(
    call: &mut HostCall<'_>,
    actor: TableId,
    name: &str,
    args: &[Value],
) -> Result<(), Error> {
    let function = field(call, actor, name)?;
    if !matches!(function, Value::Function(_) | Value::Native(_)) {
        return Err(call.error(b"actor function expected"));
    }
    let mut values = Vec::with_capacity(args.len() + 1);
    values.push(Value::Table(actor));
    values.extend_from_slice(args);
    call.call(function, &values)?;
    Ok(())
}

fn number(call: &mut HostCall<'_>, value: Value) -> Result<f32, Error> {
    sprites::number(call, value).map(|v| v as f32)
}

fn lyrics(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    name: &str,
) -> Result<TableId, Error> {
    let actor = dummy(call, store, scene, "ActorFrame", name, None)?;
    let factory = native_children::helper_function(call, b"lyric_commands")?;
    let commands = call.call(factory, &[])?[0];
    call.with_roots(&[commands], |call| {
        let commands = table(call, commands)?;
        for (name, side) in [("LyricBack", "Back"), ("LyricFront", "Front")] {
            let child = text(call, store, scene, name, "")?;
            let font = call.try_intern(b"Common Normal")?;
            set(call, child, "Font", font)?;
            let changed = get(call, commands, side.as_bytes())?;
            set(call, child, "ChangedCommand", changed)?;
            append(call, store, actor, child)?;
            named(call, store, actor, name, child)?;
        }
        for name in [
            "SetNoReverseCommand",
            "SetReverseCommand",
            "SetOneReverseCommand",
        ] {
            let function = get(call, commands, name.as_bytes())?;
            set(call, actor, name, function)?;
        }
        let initial = native_children::helper_function(call, b"lyric_initial")?;
        let initial = call.call(initial, &[])?[0];
        let initial = assets::text(call, initial)?;
        let function = get(call, commands, format!("{initial}Command").as_bytes())?;
        call.call(function, &[Value::Table(actor)])?;
        Ok(actor)
    })
}

fn background(call: &mut HostCall<'_>, store: &Shared, scene: u64) -> Result<TableId, Error> {
    let actor = dummy(call, store, scene, "ActorFrame", "SongBackground", None)?;
    let implementation = dummy(call, store, scene, "ActorFrame", "", None)?;
    append(call, store, actor, implementation)?;
    let globals = table(call, helper(call, 5)?)?;
    let width = field(call, globals, "SCREEN_WIDTH")?;
    let width = number(call, width)?;
    let height = field(call, globals, "SCREEN_HEIGHT")?;
    let height = number(call, height)?;
    for (left, top, right, bottom) in [
        (0., 0., 0., height),
        (0., 0., width, 0.),
        (width, 0., width, height),
        (0., height, width, height),
    ] {
        let quad = dummy(call, store, scene, "Quad", "", Some(implementation))?;
        invoke(
            call,
            quad,
            "stretchto",
            &[left, top, right, bottom].map(|n| Value::Number(n as f64)),
        )?;
        invoke(call, quad, "diffuse", &[0., 0., 0., 1.].map(Value::Number))?;
        append(call, store, implementation, quad)?;
    }
    let brightness = dummy(call, store, scene, "ActorFrame", "", Some(implementation))?;
    append(call, store, implementation, brightness)?;
    let side = width / 2. - 20.;
    let prefs = get(call, globals, b"PREFSMAN")?;
    let level = call.with_roots(&[prefs], |call| {
        let function = field(call, table(call, prefs)?, "GetPreference")?;
        call.with_roots(&[function], |call| {
            if !matches!(function, Value::Function(_) | Value::Native(_)) {
                return Err(call.error(b"preference function expected"));
            }
            let key = call.try_intern(b"BGBrightness")?;
            let value = call
                .call(function, &[prefs, key])?
                .first()
                .copied()
                .unwrap_or(Value::Nil);
            number(call, value)
        })
    })?;
    for (left, right) in [(0., side), (width - side, width), (side, width - side)] {
        let quad = dummy(
            call,
            store,
            scene,
            "Quad",
            "BrightnessOverlay",
            Some(brightness),
        )?;
        invoke(
            call,
            quad,
            "stretchto",
            &[left, 0., right, height].map(|n| Value::Number(n as f64)),
        )?;
        invoke(
            call,
            quad,
            "diffuse",
            &[0., 0., 0., (1. - level) as f64].map(Value::Number),
        )?;
        append(call, store, brightness, quad)?;
    }
    // BackgroundImpl enables owned lookups recursively on its frame nodes.
    for frame in [actor, implementation, brightness] {
        set(
            call,
            frame,
            "__songlua_owned_child_lookup",
            Value::Boolean(true),
        )?;
    }
    Ok(actor)
}

