pub(super) fn initialize(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<(), Error> {
    let key = call.try_intern(b"FOV")?;
    let value = call.raw_table_get(actor, key)?;
    if value != Value::Nil {
        scalar(
            store,
            actor,
            "fov",
            super::sprites::number(call, value)? as f32,
        );
    }
    Ok(())
}

pub(super) fn text<'a>(call: &'a HostCall<'_>, value: Value) -> Option<&'a str> {
    let Value::String(id) = value else {
        return None;
    };
    std::str::from_utf8(call.string_bytes(id)?).ok()
}

fn alignment(call: &HostCall<'_>, value: Value, vertical: bool) -> Option<f32> {
    if let Some(number) = float_scalar(call, value, false) {
        return Some(number);
    }
    let token = crate::borrowed_alignment_token(text(call, value)?);
    if token.eq_ignore_ascii_case(if vertical { "top" } else { "left" }) {
        Some(0.0)
    } else if token.eq_ignore_ascii_case("center") || token.eq_ignore_ascii_case("middle") {
        Some(0.5)
    } else if token.eq_ignore_ascii_case(if vertical { "bottom" } else { "right" }) {
        Some(1.0)
    } else {
        None
    }
}

pub(super) fn color(call: &mut HostCall<'_>) -> Result<Option<[f32; 4]>, Error> {
    color_at(call, 1)
}
pub(super) fn color_at(call: &mut HostCall<'_>, offset: usize) -> Result<Option<[f32; 4]>, Error> {
    match arg(call, offset) {
        Value::Table(table) => {
            let mut out = [1.0; 4];
            for (i, component) in out.iter_mut().enumerate() {
                let value = call.raw_table_get(table, Value::Number((i + 1) as f64))?;
                if i == 3 && value == Value::Nil {
                    continue;
                }
                // The production table reader uses Lua numeric coercion, which
                // accepts hex strings and nonfinite numbers. It ignores __index.
                let converted = call.call(helper(call, 6)?, &[value])?[0];
                let Value::Number(number) = converted else {
                    return Ok(None);
                };
                *component = number as f32;
            }
            Ok(Some(out))
        }
        Value::String(_) => Ok(text(call, arg(call, offset))
            .map(|text| crate::parse_color_text(text).unwrap_or([1.0; 4]))),
        first => {
            let Some(r) = float_scalar(call, first, false) else {
                return Ok(None);
            };
            let Some(g) = float_scalar(call, arg(call, offset + 1), false) else {
                return Ok(None);
            };
            let Some(b) = float_scalar(call, arg(call, offset + 2), false) else {
                return Ok(None);
            };
            Ok(Some([
                r,
                g,
                b,
                float_scalar(call, arg(call, offset + 3), false).unwrap_or(1.0),
            ]))
        }
    }
}

fn push_color(call: &mut HostCall<'_>, color: [f32; 4]) -> Result<(), Error> {
    let table = call.try_new_table()?;
    call.with_roots(&[Value::Table(table)], |call| {
        for (i, component) in color.into_iter().enumerate() {
            call.raw_table_set(
                table,
                Value::Number((i + 1) as f64),
                Value::Number(component as f64),
            )?;
        }
        call.push(Value::Table(table))
    })
}

fn strict_boolean(call: &HostCall<'_>, name: &str) -> Result<bool, Error> {
    match arg(call, 1) {
        Value::Boolean(value) => Ok(value),
        Value::Number(value) => Ok(value.trunc() != 0.0),
        _ => Err(call.error(format!("{name} expects a boolean or number").as_bytes())),
    }
}

fn cull_mode(call: &HostCall<'_>) -> Result<CullMode, Error> {
    match arg(call, 1) {
        Value::Number(0.0) => Ok(CullMode::Back),
        Value::Number(1.0) => Ok(CullMode::Front),
        Value::Number(2.0) => Ok(CullMode::None),
        value => match text(call, value) {
            Some("CullMode_Back") => Ok(CullMode::Back),
            Some("CullMode_Front") => Ok(CullMode::Front),
            Some("CullMode_None") => Ok(CullMode::None),
            Some(value) if value.eq_ignore_ascii_case("back") => Ok(CullMode::Back),
            Some(value) if value.eq_ignore_ascii_case("front") => Ok(CullMode::Front),
            Some(value) if value.eq_ignore_ascii_case("none") => Ok(CullMode::None),
            _ => Err(call.error(b"invalid CullMode")),
        },
    }
}

fn depth(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    test: Option<(bool, bool)>,
    write: Option<bool>,
) -> Result<(), Error> {
    {
        let mut store = store.lock().unwrap();
        let render = &mut store.actors.get_mut(&actor).unwrap().state.render;
        if let Some((enabled, on_fail)) = test {
            render.depth_test = enabled;
            render.depth_test_on_fail = on_fail;
        }
        if let Some(enabled) = write {
            render.depth_write = enabled;
        }
    }
    for child in children(call, store, actor)? {
        depth(call, store, child, test, write)?;
    }
    Ok(())
}

pub(super) fn method(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    let value = arg(call, 1);
    // Parse values before taking the metadata lock. Lua numeric conversion and
    // return-table allocation may reenter the VM or collect traced captures.
    if matches!(name, "GetDiffuse" | "GetGlow") {
        let color = {
            let store = store.lock().unwrap();
            let pose = store.actors[&actor].destination();
            if name == "GetDiffuse" {
                pose.diffuse
            } else {
                pose.glow
            }
        };
        return push_color(call, color);
    }
    if name == "getrotation" {
        let rotation = store.lock().unwrap().actors[&actor].state.rotation;
        for value in rotation {
            call.push(Value::Number(value as f64))?;
        }
        return Ok(());
    }
    if name.starts_with("Get") {
        let value = {
            let store = store.lock().unwrap();
            let actor = &store.actors[&actor];
            let render = &actor.state.render;
            match name {
                "GetDiffuseAlpha" => actor.destination().diffuse[3],
                "GetBaseZoomX" => render.basezoom_x,
                "GetBaseZoomY" => render.basezoom_y,
                "GetBaseZoomZ" => render.basezoom_z,
                "GetHAlign" => render.halign,
                "GetVAlign" => render.valign,
                _ => unreachable!(),
            }
        };
        return call.push(Value::Number(value as f64));
    }
    if matches!(name, "diffuse" | "diffusecolor" | "glow" | "shadowcolor")
        || corner_mask(name).is_some()
    {
        if let Some(mut color) = color(call)? {
            let mut store = store.lock().unwrap();
            let sync = !store.playback && matches!(name, "diffuse" | "diffusecolor");
            let actor = store.actors.get_mut(&actor).unwrap();
            if name == "shadowcolor" {
                actor.state.render.shadow_color = color;
            } else {
                let pose = actor.destination_mut();
                if let Some(mask) = corner_mask(name) {
                    for (i, vertex) in pose
                        .vertex_colors
                        .get_or_insert([[1.0; 4]; 4])
                        .iter_mut()
                        .enumerate()
                    {
                        if mask & (1 << i) != 0 {
                            *vertex = color;
                        }
                    }
                } else if name == "glow" {
                    pose.glow = color;
                } else {
                    if name == "diffusecolor" {
                        color[3] = pose.diffuse[3];
                    }
                    pose.diffuse = color;
                }
            }
            if sync {
                actor.sync_rotation_getters();
            }
        }
    } else if matches!(name, "halign" | "valign" | "horizalign" | "vertalign") {
        let align = alignment(call, value, matches!(name, "valign" | "vertalign"));
        let text_align = (name == "horizalign")
            .then(|| text(call, value).and_then(crate::parse_overlay_text_align))
            .flatten();
        let mut store = store.lock().unwrap();
        let render = &mut store.actors.get_mut(&actor).unwrap().state.render;
        if let Some(value) = align {
            if matches!(name, "valign" | "vertalign") {
                render.valign = value;
            } else {
                render.halign = value;
            }
        }
        if let Some(value) = text_align {
            render.text_align = value;
        }
    } else if name == "backfacecull" || name == "cullmode" {
        let mode = if name == "backfacecull" {
            if strict_boolean(call, name)? {
                CullMode::Back
            } else {
                CullMode::None
            }
        } else {
            cull_mode(call)?
        };
        store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .unwrap()
            .state
            .render
            .cull_mode = mode;
    } else if matches!(name, "zbuffer" | "ztest" | "zwrite") {
        let enabled = strict_boolean(call, name)?;
        depth(
            call,
            store,
            actor,
            (name != "zwrite").then_some((enabled, false)),
            (name != "ztest").then_some(enabled),
        )?;
    } else if name == "ztestmode" {
        let mode = text(call, value).ok_or_else(|| call.error(b"ztestmode expects a ZTestMode"))?;
        let flags = match mode
            .trim()
            .trim_start_matches("ZTestMode_")
            .to_ascii_lowercase()
            .as_str()
        {
            "off" => (false, false),
            "writeonpass" => (true, false),
            "writeonfail" => (true, true),
            _ => return Err(call.error(format!("invalid ZTestMode: {mode}").as_bytes())),
        };
        depth(call, store, actor, Some(flags), None)?;
    } else if matches!(name, "SetTextureFiltering" | "SetDrawByZPosition") {
        let enabled = call
            .arguments()
            .get(1)
            .is_none_or(|v| !matches!(v, Value::Nil | Value::Boolean(false)));
        let mut store = store.lock().unwrap();
        let render = &mut store.actors.get_mut(&actor).unwrap().state.render;
        if name == "SetTextureFiltering" {
            render.texture_filtering = enabled;
        } else {
            render.draw_by_z_position = enabled;
        }
    } else if name == "blend" {
        if let Some(blend) = text(call, value).and_then(crate::parse_overlay_blend_mode) {
            store
                .lock()
                .unwrap()
                .actors
                .get_mut(&actor)
                .unwrap()
                .state
                .render
                .blend = blend;
        }
    } else if matches!(
        name,
        "stretchto"
            | "scaletofit"
            | "scaletocover"
            | "zoomto"
            | "zoomtowidth"
            | "zoomtoheight"
            | "vanishpoint"
    ) {
        geometry(call, store, actor, name)?;
    } else if name != "clearzbuffer" {
        let nonfinite = matches!(
            name,
            "croptop"
                | "cropbottom"
                | "fadeleft"
                | "faderight"
                | "fadetop"
                | "fadebottom"
                | "basealpha"
                | "heading"
                | "pitch"
                | "roll"
        ) || (name == "diffusealpha"
            && matches!(value, Value::Number(v) if v.is_infinite()));
        if let Some(number) = float_scalar(call, value, nonfinite) {
            scalar(store, actor, name, number);
        }
    }
    call.push(Value::Table(actor))
}

fn corner_mask(name: &str) -> Option<u8> {
    Some(match name {
        "diffuseupperleft" => 1,
        "diffuseupperright" => 2,
        "diffuselowerleft" => 4,
        "diffuselowerright" => 8,
        "diffuseleftedge" => 5,
        "diffuserightedge" => 10,
        "diffusetopedge" => 3,
        "diffusebottomedge" => 12,
        _ => return None,
    })
}

fn scalar(store: &Shared, actor: TableId, name: &str, value: f32) {
    let mut store = store.lock().unwrap();
    let sync = name == "diffusealpha" && !store.playback;
    let actor = store.actors.get_mut(&actor).unwrap();
    let render = &mut actor.state.render;
    match name {
        "basealpha" => render.base_alpha = value,
        "basezoom" => {
            render.basezoom = value;
            render.basezoom_x = value;
            render.basezoom_y = value;
            render.basezoom_z = value;
        }
        "basezoomx" => render.basezoom_x = value,
        "basezoomy" => render.basezoom_y = value,
        "basezoomz" => render.basezoom_z = value,
        "baserotationx" => render.base_rotation[0] = value,
        "baserotationy" => render.base_rotation[1] = value,
        "baserotationz" => render.base_rotation[2] = value,
        "shadowlength" => render.shadow_len = [value, -value],
        "shadowlengthx" => render.shadow_len[0] = value,
        "shadowlengthy" => render.shadow_len[1] = -value,
        "zbias" => render.z_bias = value,
        "fov" => render.fov = (value != -1.0).then_some(value),
        _ => {
            let pose = actor.destination_mut();
            match name {
                "cropleft" => pose.cropleft = value,
                "cropright" => pose.cropright = value,
                "croptop" => pose.croptop = value,
                "cropbottom" => pose.cropbottom = value,
                "fadeleft" => pose.fadeleft = value,
                "faderight" => pose.faderight = value,
                "fadetop" => pose.fadetop = value,
                "fadebottom" => pose.fadebottom = value,
                "skewx" => pose.skew_x = value,
                "skewy" => pose.skew_y = value,
                "diffusealpha" => pose.diffuse[3] = value,
                "heading" | "pitch" | "roll" => {
                    let axis = match name {
                        "heading" => 1,
                        "pitch" => 0,
                        _ => 2,
                    };
                    pose.quaternion = crate::actor_quaternion::rotate(pose.quaternion, axis, value);
                }
                _ => unreachable!(),
            }
        }
    }
    if sync {
        actor.sync_rotation_getters();
    }
}

fn geometry(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    let count = match name {
        "zoomtowidth" | "zoomtoheight" => 1,
        "zoomto" | "vanishpoint" => 2,
        _ => 4,
    };
    let mut values = [0.0; 4];
    for (i, value) in values.iter_mut().enumerate().take(count) {
        match float_scalar(call, arg(call, i + 1), false) {
            Some(number) => *value = number,
            None if name == "stretchto" => {}
            None => return Ok(()),
        }
    }
    if name != "vanishpoint" {
        super::sprites::refresh_size(call, store, actor)?;
    }
    let bitmap = store.lock().unwrap().actors[&actor].state.class == "BitmapText";
    let text_height =
        bitmap && name == "zoomtoheight" && !super::text::content(call, actor)?.is_empty();
    let id = actor;
    let mut guard = store.lock().unwrap();
    let actor = guard.actors.get_mut(&id).unwrap();
    if bitmap && (matches!(name, "zoomto" | "zoomtowidth") || text_height) {
        let [width, height] = actor.state.size.map(f32::abs);
        let size = match name {
            "zoomtowidth" => [values[0], height],
            "zoomtoheight" => [width, values[0]],
            _ => [values[0], values[1]],
        };
        actor.state.size = size;
        actor.state.render.size = Some(size);
        return Ok(());
    }
    let mut scaled = false;
    let [width, height] = actor.state.size.map(f32::abs);
    let render = &mut actor.state.render;
    if name == "vanishpoint" {
        render.vanishpoint = Some([values[0], values[1]]);
        return Ok(());
    }
    let align = [render.halign, render.valign];
    let pose = actor.destination_mut();
    match name {
        "zoomtowidth" => pose.zoom_x = values[0] / width,
        "zoomtoheight" => pose.zoom_y = values[0] / height,
        "zoomto" => {
            pose.zoom_x = values[0] / width;
            pose.zoom_y = values[1] / height;
        }
        "stretchto" => {
            let w = values[2] - values[0];
            let h = values[3] - values[1];
            pose.x = values[0] + w / 2.0;
            pose.y = values[1] + h / 2.0;
            pose.zoom_x = w / width;
            pose.zoom_y = h / height;
        }
        "scaletofit" | "scaletocover" => {
            if let Some(plan) =
                crate::scale_to_rect_plan(values, [width, height], align, name == "scaletocover")
            {
                scaled = true;
                pose.x = plan.pos[0];
                pose.y = plan.pos[1];
                pose.zoom = plan.zoom;
                pose.zoom_x = plan.zoom;
                pose.zoom_y = plan.zoom;
                pose.zoom_z = plan.zoom;
                if plan.flip_x {
                    pose.rot_y_deg = 180.0;
                }
                if plan.flip_y {
                    pose.rot_x_deg = 180.0;
                }
                if plan.flip_x {
                    actor.state.rotation[1] = 180.0;
                }
                if plan.flip_y {
                    actor.state.rotation[0] = 180.0;
                }
            }
        }
        _ => unreachable!(),
    }
    drop(guard);
    if scaled {
        super::text::pre_zoom(call, store, id, true, true)?;
    }
    Ok(())
}

//! Named native children shared by composite actor bindings.
use super::*;
use sprites::set;

pub(super) fn install_helpers(vm: &mut Vm, actor: TableId, helpers: TableId) -> Result<(), Error> {
    let setup = compile_named(
        include_bytes!("native_children.lua"),
        b"=DeadSync native children",
    )?;
    let setup = vm.execute(&setup)?[0];
    let root = vm.pin(setup)?;
    let key = vm.try_intern(b"GetName")?;
    let get_name = vm.raw_table_get(actor, key)?;
    let group = vm.raw_table_get(helpers, Value::Number(3.0))?;
    let functions = vm.call(setup, &[group, get_name])?.to_vec();
    for (key, function) in [
        "native_registry",
        "native_named_children",
        "native_children",
        "native_is_group",
    ]
    .into_iter()
    .zip(functions)
    {
        super::super::put(vm, helpers, key, function)?;
    }
    vm.unpin(root)?;
    Ok(())
}

pub(super) fn helper_function(call: &mut HostCall<'_>, name: &[u8]) -> Result<Value, Error> {
    let helpers = table(call, call.captures()[1])?;
    get(call, helpers, name)
}

pub(super) fn named_children(call: &mut HostCall<'_>, actor: TableId) -> Result<Value, Error> {
    let function = helper_function(call, b"native_named_children")?;
    Ok(call.call(function, &[Value::Table(actor)])?[0])
}

pub(super) fn children(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<Vec<TableId>, Error> {
    let function = helper_function(call, b"native_children")?;
    let values = call.call(function, &[Value::Table(actor)])?[0];
    call.with_roots(&[values], |call| {
        let values = table(call, values)?;
        let mut result = Vec::new();
        for i in 1..=call.raw_table_len(values)? {
            let value = call.raw_table_get(values, Value::Number(i as f64))?;
            let id = table(call, value)?;
            if !store.lock().unwrap().actors.contains_key(&id) {
                return Err(call.error(b"native child is not owned by this runtime"));
            }
            result.push(id);
        }
        Ok(result)
    })
}

pub(super) fn state(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<crate::SongLuaOverlayState, Error> {
    if !store.lock().unwrap().actors.contains_key(&actor) {
        let is_group = helper_function(call, b"native_is_group")?;
        if call.call(is_group, &[Value::Table(actor)])?[0] == Value::Boolean(true) {
            return Ok(crate::SongLuaOverlayState::default());
        }
    }
    let store = store.lock().unwrap();
    let actor = store
        .actors
        .get(&actor)
        .ok_or_else(|| call.error(b"graph render child has been released"))?;
    let mut state = actor.state.render;
    actor.destination().write_to(&mut state);
    [state.rot_x_deg, state.rot_y_deg, state.rot_z_deg] = actor.state.rotation;
    state.visible = actor.state.visible;
    state.draw_order = actor.state.draw_order;
    state.hibernating = actor.hibernate > 0.0;
    Ok(state)
}

pub(super) fn insert(
    call: &mut HostCall<'_>,
    actor: TableId,
    key: &str,
    value: Value,
) -> Result<(), Error> {
    call.with_roots(&[value], |call| {
        let registry = helper_function(call, b"native_registry")?;
        let registry = call.call(registry, &[Value::Table(actor)])?[0];
        call.with_roots(&[registry], |call| {
            set(call, table(call, registry)?, key, value)
        })
    })
}

pub(super) fn group_members(
    call: &mut HostCall<'_>,
    group: TableId,
) -> Result<Vec<TableId>, Error> {
    let check = helper_function(call, b"native_is_group")?;
    if call.call(check, &[Value::Table(group)])?[0] != Value::Boolean(true) {
        return Err(call.error(b"native child is not an actor or a generated child group"));
    }
    let mut members = Vec::new();
    for i in 1..=call.raw_table_len(group)? {
        members.push(table(
            call,
            call.raw_table_get(group, Value::Number(i as f64))?,
        )?);
    }
    Ok(members)
}

pub(super) fn adopt(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    parent: TableId,
) -> Result<(), Error> {
    set(call, actor, "__songlua_parent", Value::Table(parent))?;
    if let Some(actor) = store.lock().unwrap().actors.get_mut(&actor) {
        actor.parent = Some(parent);
    }
    Ok(())
}

pub(super) fn adopt_declared(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    parent: TableId,
) -> Result<(), Error> {
    let kind = call.try_intern(b"__songlua_actor_type")?;
    let value = call.raw_table_get(parent, kind)?;
    if value == Value::Nil {
        return Ok(());
    }
    assets::text(call, value)?;
    let key = call.try_intern(b"__songlua_parent")?;
    call.raw_table_set(actor, key, Value::Table(parent))?;
    if let Some(actor) = store.lock().unwrap().actors.get_mut(&actor) {
        actor.parent = Some(parent);
    }
    Ok(())
}

pub(super) fn group_lifecycle(
    call: &mut HostCall<'_>,
    store: &Shared,
    group: TableId,
    startup: bool,
) -> Result<(), Error> {
    call.with_roots(&[Value::Table(group)], |call| {
        let children = group_members(call, group)?;
        // A fresh group forwards the lifecycle guard to its last child, just
        // like any other instance field. Authored children have already run.
        if children.last().is_some_and(|child| {
            store
                .lock()
                .unwrap()
                .actors
                .get(child)
                .is_some_and(|a| if startup { a.started } else { a.initialized })
        }) {
            return Ok(());
        }
        if startup && let Some((function, _)) = command(call, group, b"On")? {
            run_scoped(call, group, function, None)?;
        }
        for child in children {
            adopt_declared(call, store, child, group)?;
            if startup {
                lifecycle::startup(call, store, child)?;
            } else {
                initialize(call, store, child)?;
            }
        }
        if !startup && let Some((function, _)) = command(call, group, b"Init")? {
            run_scoped(call, group, function, None)?;
        }
        Ok(())
    })
}

//! Existing StepsDisplay children, SetInternal ordering and gameplay metrics.
use super::*;
use sprites::field;

const COMMANDS: &[u8] = br#"return function()
return {
    FrameLoadCommand = function(self,param) local bFlip = param.PlayerState and param.PlayerState:GetPlayerNumber() ~= PLAYER_1; self:zoomx(bFlip and -1 or 1); end,
    FrameSetCommand = function(self,param) if param.CustomDifficulty and param.CustomDifficulty ~= "" then self:diffuse(CustomDifficultyToColor(param.CustomDifficulty)) end end,
    MeterOnCommand = function(self) self:visible(false) end,
    MeterSetCommand = function(self,param) MESSAGEMAN:Broadcast("MeterSet") end,
    DescriptionOnCommand = function(self) self:zoom(0.8):horizalign("left"):vertspacing(-9):_wrapwidthpixels(345) end,
    DescriptionSetCommand = function(self,params) self:visible(params.Steps ~= nil and params.Steps:GetDifficulty()=="Difficulty_Edit") end,
}
end"#;

#[derive(Clone)]
struct Binding {
    store: Shared,
    method: &'static str,
}

impl Actors {
    pub(in crate::rust_engine) fn initialize_steps_displays(
        &self,
        vm: &mut Vm,
        screen: Value,
    ) -> Result<(), Error> {
        ensure_helpers(vm, self.helpers)?;
        let function = vm.new_host_function_with_data(
            initialize_callback,
            &[Value::Table(self.registry), Value::Table(self.helpers)],
            self.store.clone(),
        )?;
        vm.call(function, &[screen]).map(|_| ())
    }
}

pub(super) fn ensure_helpers(vm: &mut Vm, helpers: TableId) -> Result<(), Error> {
    let key = vm.try_intern(b"steps_display_commands")?;
    if vm.raw_table_get(helpers, key)? == Value::Nil {
        let code = compile_named(COMMANDS, b"@theme:/metrics.ini:StepsDisplayGameplay")?;
        let factory = vm.execute(&code)?[0];
        super::super::put(vm, helpers, "steps_display_commands", factory)?;
    }
    Ok(())
}

fn raw(call: &mut HostCall<'_>, actor: TableId, name: &str, value: Value) -> Result<(), Error> {
    let key = call.try_intern(name.as_bytes())?;
    call.raw_table_set(actor, key, value)
}

pub(super) fn create(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    name: &str,
) -> Result<TableId, Error> {
    let actor = generated_players::dummy(call, store, scene, "StepsDisplay", name, None)?;
    raw(
        call,
        actor,
        "__songlua_owned_child_lookup",
        Value::Boolean(true),
    )?;
    for (name, kind) in [
        ("Frame", "Sprite"),
        ("Meter", "BitmapText"),
        ("Description", "BitmapText"),
        ("Autogen", "Sprite"),
    ] {
        let child = generated_players::dummy(call, store, scene, kind, name, Some(actor))?;
        if kind == "Sprite" {
            screen_parts::blank_texture(call, store, child)?;
        } else {
            let font = call.try_intern(b"Common Normal")?;
            raw(call, child, "Font", font)?;
            let empty = call.try_intern(b"")?;
            raw(call, child, "Text", empty)?;
        }
        screen_parts::append(call, store, actor, child)?;
        screen_parts::named(call, store, actor, name, child)?;
    }
    let bound = get(call, actor, b"__songlua_bound_methods")?;
    let bound = table(call, bound)?;
    for method in ["SetFromSteps", "SetFromTrail", "SetFromGameState"] {
        let function = call.new_host_function_with_data(
            invoke,
            &[call.captures()[0], call.captures()[1]],
            Binding {
                store: store.clone(),
                method,
            },
        )?;
        raw(call, bound, method, function)?;
    }
    Ok(actor)
}

fn value_call(
    call: &mut HostCall<'_>,
    receiver: TableId,
    method: &str,
    arguments: &[Value],
) -> Result<Value, Error> {
    let function = field(call, receiver, method)?;
    if !matches!(function, Value::Function(_) | Value::Native(_)) {
        return Err(call.error(b"function expected"));
    }
    let mut args = Vec::with_capacity(arguments.len() + 1);
    args.push(Value::Table(receiver));
    args.extend_from_slice(arguments);
    Ok(call
        .call(function, &args)?
        .first()
        .copied()
        .unwrap_or(Value::Nil))
}

fn truthy(value: Value) -> bool {
    !matches!(value, Value::Nil | Value::Boolean(false))
}

fn optional_table(call: &HostCall<'_>, value: Value) -> Result<Option<TableId>, Error> {
    if value == Value::Nil {
        Ok(None)
    } else {
        table(call, value).map(Some)
    }
}

fn visibility(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    visible: bool,
) -> Result<(), Error> {
    raw(call, actor, "__songlua_visible", Value::Boolean(visible))?;
    if let Some(actor) = store.lock().unwrap().actors.get_mut(&actor) {
        actor.state.visible = visible;
    }
    Ok(())
}

fn registry(call: &mut HostCall<'_>, actor: TableId) -> Result<Value, Error> {
    let function = native_children::helper_function(call, b"native_registry")?;
    Ok(call.call(function, &[Value::Table(actor)])?[0])
}

fn child(call: &mut HostCall<'_>, registry: TableId, name: &str) -> Result<TableId, Error> {
    let value = get(call, registry, name.as_bytes())?;
    table(call, value)
}

fn with_children(
    call: &mut HostCall<'_>,
    actor: TableId,
    mut action: impl FnMut(&mut HostCall<'_>, TableId) -> Result<(), Error>,
) -> Result<(), Error> {
    let helper = native_children::helper_function(call, b"native_children")?;
    let children = call.call(helper, &[Value::Table(actor)])?[0];
    // Native direct-child enumeration owns its snapshot even when a callback
    // removes a plain table child from the current registry and collects.
    call.with_roots(&[children], |call| {
        let children = table(call, children)?;
        for index in 1..=call.raw_table_len(children)? {
            let value = call.raw_table_get(children, Value::Number(index as f64))?;
            action(call, table(call, value)?)?;
        }
        Ok(())
    })
}

fn run_command(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &[u8],
    params: Option<Value>,
) -> Result<(), Error> {
    if store.lock().unwrap().actors.contains_key(&actor) {
        return run_named(call, store, actor, name, params);
    }
    // These setters accept a table receiver, and native named registries can
    // contain plain callback tables. Preserve their guard without treating an
    // unowned table as an entry in the Rust actor store.
    let Some((function, command_field)) = command(call, actor, name)? else {
        return Ok(());
    };
    call.with_roots(
        &[Value::Table(actor), function, params.unwrap_or(Value::Nil)],
        |call| {
            let active = field(call, actor, "__songlua_active_commands")?;
            let active = if active == Value::Nil {
                let value = Value::Table(call.try_new_table()?);
                sprites::set(call, actor, "__songlua_active_commands", value)?;
                value
            } else {
                active
            };
            table(call, active)?;
            call.with_roots(&[active], |call| {
                let key = call.try_intern(&command_field)?;
                call.with_roots(&[key], |call| {
                    if truthy(call.table_get(active, key)?) {
                        return Ok(());
                    }
                    call.table_set(active, key, Value::Boolean(true))?;
                    let result = (|| {
                        let theme =
                            call.call(helper(call, 4)?, &[function])?[0] == Value::Boolean(true);
                        match run_scoped(call, actor, function, params) {
                            Err(error) if theme && error.kind() == ErrorKind::Runtime => {
                                store.lock().unwrap().diagnostics.push(error.to_string());
                                Ok(())
                            }
                            result => result,
                        }
                    })();
                    call.table_set(active, key, Value::Nil)?;
                    result
                })
            })
        },
    )
}

fn direct_message(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &[u8],
    params: Value,
) -> Result<(), Error> {
    call.with_roots(&[Value::Table(actor), params], |call| {
        run_command(call, store, actor, name, Some(params))?;
        let kind = assets::field(call, actor, b"__songlua_actor_type")?.unwrap_or_default();
        if ["ActorFrame", "ActorFrameTexture", "TopScreen"]
            .iter()
            .any(|k| kind.eq_ignore_ascii_case(k))
        {
            with_children(call, actor, |call, child| {
                direct_message(call, store, child, name, params)
            })?;
        }
        Ok(())
    })
}

fn set_value(
    call: &mut HostCall<'_>,
    store: &Shared,
    display: TableId,
    value: Option<TableId>,
    trail: bool,
) -> Result<(), Error> {
    call.with_roots(&[value.map_or(Value::Nil, Value::Table)], |call| {
        let (difficulty, steps_type, meter) = if let Some(value) = value {
            let difficulty = value_call(call, value, "GetDifficulty", &[])?;
            let difficulty = assets::text(call, difficulty)?;
            let steps_type = value_call(call, value, "GetStepsType", &[])?;
            let steps_type = assets::text(call, steps_type)?;
            let meter = value_call(call, value, "GetMeter", &[])?;
            let meter = sprites::number(call, meter)?.trunc();
            if !(i32::MIN as f64..=i32::MAX as f64).contains(&meter) {
                return Err(call.error(b"steps meter is out of range"));
            }
            (difficulty, steps_type, meter as i32)
        } else {
            let difficulty = get(call, display, b"__songlua_preferred_difficulty")?;
            (
                assets::text(call, difficulty)?,
                "StepsType_Invalid".into(),
                0,
            )
        };
        let short = difficulty
            .strip_prefix("Difficulty_")
            .unwrap_or(&difficulty);
        let custom = match (steps_type.as_str(), short) {
            ("StepsType_Pump_Single", "Hard") => "Crazy",
            ("StepsType_Pump_Double", "Medium") => "Freestyle",
            ("StepsType_Pump_Double", "Hard") => "Nightmare",
            ("StepsType_Pump_Halfdouble", "Medium") => "HalfDouble",
            (_, "Invalid") => "",
            _ => short,
        };
        let description = if !trail
            && short == "Edit"
            && let Some(value) = value
        {
            let text = value_call(call, value, "GetDescription", &[])?;
            assets::text(call, text)?
        } else {
            match custom {
                "Beginner" => "Novice",
                "Challenge" => "Expert",
                _ => custom,
            }
            .into()
        };
        let params = call.try_new_table()?;
        call.with_roots(&[Value::Table(params)], |call| {
            for (key, text) in [
                ("CustomDifficulty", custom),
                ("DisplayDescription", description.as_str()),
                ("StepsType", steps_type.as_str()),
            ] {
                let value = call.try_intern(text.as_bytes())?;
                raw(call, params, key, value)?;
            }
            raw(call, params, "Meter", Value::Number(meter as f64))?;
            if let Some(value) = value {
                raw(
                    call,
                    params,
                    if trail { "Trail" } else { "Steps" },
                    Value::Table(value),
                )?;
            }
            let params = Value::Table(params);
            visibility(call, store, display, true)?;
            let children = registry(call, display)?;
            call.with_roots(&[children], |call| {
                let children = table(call, children)?;
                // Native Table handles keep every selected child alive until
                // SetInternal returns, even after callbacks replace its registry.
                let held = call.try_new_table()?;
                call.with_roots(&[Value::Table(held)], |call| {
                    let frame = child(call, children, "Frame")?;
                    call.raw_table_set(held, Value::Number(1.), Value::Table(frame))?;
                    direct_message(call, store, frame, b"Set", params)?;
                    let text = child(call, children, "Meter")?;
                    call.raw_table_set(held, Value::Number(2.), Value::Table(text))?;
                    let meter_text = if meter == 0 {
                        "?".into()
                    } else {
                        meter.to_string()
                    };
                    let meter_text = call.try_intern(meter_text.as_bytes())?;
                    raw(call, text, "Text", meter_text)?;
                    if meter != 0 {
                        direct_message(call, store, text, b"Set", params)?;
                    }
                    let text = child(call, children, "Description")?;
                    call.raw_table_set(held, Value::Number(3.), Value::Table(text))?;
                    let description = call.try_intern(description.as_bytes())?;
                    raw(call, text, "Text", description)?;
                    direct_message(call, store, text, b"Set", params)?;
                    let autogen = child(call, children, "Autogen")?;
                    call.raw_table_set(held, Value::Number(4.), Value::Table(autogen))?;
                    call.with_roots(&[Value::Table(autogen)], |call| {
                        direct_message(call, store, autogen, b"Set", params)?;
                        let autogen_value = if !trail && let Some(value) = value {
                            truthy(value_call(call, value, "IsAutogen", &[])?)
                        } else {
                            false
                        };
                        visibility(call, store, autogen, autogen_value)
                    })?;
                    run_command(call, store, display, b"Set", Some(params))?;
                    with_children(call, display, |call, child| {
                        direct_message(call, store, child, b"Set", params)
                    })
                })
            })
        })
    })
}

fn invoke(call: &mut HostCall<'_>) -> Result<(), Error> {
    let Binding { store, method } = call.function_data::<Binding>().unwrap().clone();
    let display = table(call, arg(call, 0))?;
    let value = arg(call, 1);
    if method == "SetFromGameState" {
        let globals = table(call, helper(call, 5)?)?;
        let game = field(call, globals, "GAMESTATE")?;
        call.with_roots(&[game], |call| {
            let game = table(call, game)?;
            let trail = truthy(value_call(call, game, "IsCourseMode", &[])?);
            let value = value_call(
                call,
                game,
                if trail {
                    "GetCurrentTrail"
                } else {
                    "GetCurrentSteps"
                },
                &[value],
            )?;
            set_value(call, &store, display, optional_table(call, value)?, trail)
        })?;
    } else if let Some(value) = optional_table(call, value)? {
        set_value(call, &store, display, Some(value), method == "SetFromTrail")?;
    } else {
        visibility(call, &store, display, false)?;
    }
    // The typed counter conversion and increment happen only after all callbacks.
    let globals = table(call, helper(call, 5)?)?;
    let count = field(call, globals, crate::SONG_LUA_SIDE_EFFECT_COUNT_KEY)?;
    let count = if count == Value::Nil {
        0
    } else {
        let count = sprites::number(call, count)?;
        if !(i64::MIN as f64..-(i64::MIN as f64)).contains(&count) {
            return Err(call.error(b"side effect count is out of range"));
        }
        count as i64
    };
    sprites::set(
        call,
        globals,
        crate::SONG_LUA_SIDE_EFFECT_COUNT_KEY,
        Value::Number(count.saturating_add(1) as f64),
    )?;
    call.push(Value::Table(display))
}

fn initialize_callback(call: &mut HostCall<'_>) -> Result<(), Error> {
    let store = call.function_data::<Shared>().unwrap().clone();
    let screen = table(call, arg(call, 0))?;
    initialize(call, &store, screen)
}

pub(super) fn initialize(
    call: &mut HostCall<'_>,
    store: &Shared,
    screen: TableId,
) -> Result<(), Error> {
    let globals = table(call, helper(call, 5)?)?;
    let game = field(call, globals, "GAMESTATE")?;
    call.with_roots(&[game], |call| {
        let game = table(call, game)?;
        let factory = native_children::helper_function(call, b"steps_display_commands")?;
        let commands = call.call(factory, &[])?[0];
        call.with_roots(&[commands], |call| {
            let commands = table(call, commands)?;
            for index in 0..crate::LUA_PLAYERS {
                let children = registry(call, screen)?;
                let display = call.with_roots(&[children], |call| {
                    let value = get(
                        call,
                        table(call, children)?,
                        format!("StepsDisplayP{}", index + 1).as_bytes(),
                    )?;
                    optional_table(call, value)
                })?;
                let Some(display) = display else { continue };
                for (name, x) in [
                    ("Frame", 0.),
                    ("Meter", 30.),
                    ("Description", -265.),
                    ("Autogen", 40.),
                ] {
                    let children = registry(call, display)?;
                    let actor = call.with_roots(&[children], |call| {
                        child(call, table(call, children)?, name)
                    })?;
                    {
                        let mut guard = store.lock().unwrap();
                        let actor = guard.actors.get_mut(&actor).ok_or_else(|| {
                            call.error(b"steps display child is not owned by this runtime")
                        })?;
                        let pose = actor.destination_mut();
                        pose.x = x;
                        pose.y = 0.;
                    }
                    for command in ["Load", "On", "Set"] {
                        let callback =
                            get(call, commands, format!("{name}{command}Command").as_bytes())?;
                        if callback != Value::Nil {
                            raw(call, actor, &format!("{command}Command"), callback)?;
                        }
                    }
                    run_named(call, store, actor, b"On", None)?;
                }
                let player = call.try_intern(crate::player_number_name(index).as_bytes())?;
                let params = Value::Table(call.try_new_table()?);
                call.with_roots(&[player, params], |call| {
                    let state = value_call(call, game, "GetPlayerState", &[player])?;
                    table(call, state)?;
                    raw(call, table(call, params)?, "PlayerState", state)?;
                    with_children(call, display, |call, child| {
                        direct_message(call, store, child, b"Load", params)
                    })?;
                    visibility(call, store, display, false)?;
                    let steps = value_call(call, game, "GetCurrentSteps", &[player])?;
                    if let Some(steps) = optional_table(call, steps)? {
                        set_value(call, store, display, Some(steps), false)?;
                    }
                    Ok(())
                })?;
            }
            Ok(())
        })
    })
}

//! Existing game, character, memory-card, unlock and platform-hook policies.
use super::catalog::{arg, integer};
use super::fields::{Field, object, set};
use super::*;

pub(super) fn install(vm: &mut Vm) -> Result<(), Error> {
    let captures = [vm.get_global(b"_G")?, vm.get_global(b"tonumber")?];
    let initialize = vm.new_host_function(initialize, &captures)?;
    vm.call(initialize, &[]).map(|_| ())
}

fn value_method(
    call: &mut HostCall<'_>,
    owner: TableId,
    name: &str,
    value: impl Field,
) -> Result<(), Error> {
    let value = value.value(call)?;
    let method = call.new_host_function(constant, &[value])?;
    set(owner, name, method, call)
}

fn empty_method(
    call: &mut HostCall<'_>,
    owner: TableId,
    name: &str,
    count: usize,
) -> Result<(), Error> {
    let method = call.new_host_function_with_data(empty_tables, &[], count)?;
    set(owner, name, method, call)
}

fn effect_method(
    call: &mut HostCall<'_>,
    owner: TableId,
    name: &str,
    result: Value,
) -> Result<(), Error> {
    let captures = [result, call.captures()[0], call.captures()[1]];
    let method = call.new_host_function(effect, &captures)?;
    set(owner, name, method, call)
}

fn initialize(call: &mut HostCall<'_>) -> Result<(), Error> {
    let globals = table(call, call.captures()[0])?;
    let gameman = object(call, |call, owner| {
        let method = call.new_host_function(styles, &[])?;
        set(owner, "GetStylesForGame", method, call)
    })?;
    set(globals, "GAMEMAN", gameman, call)?;
    let charman = object(call, |call, owner| {
        empty_method(call, owner, "GetAllCharacters", 1)?;
        value_method(call, owner, "GetCharacterCount", 0_i32)?;
        for name in ["GetCharacter", "GetDefaultCharacter", "GetRandomCharacter"] {
            value_method(call, owner, name, Value::Nil)?;
        }
        Ok(())
    })?;
    set(globals, "CHARMAN", charman, call)?;
    let memcardman = object(call, |call, owner| {
        value_method(call, owner, "GetCardState", "MemoryCardState_none")?;
        value_method(call, owner, "GetName", "")?;
        for name in ["MountCard", "UnmountCard"] {
            effect_method(call, owner, name, Value::Boolean(false))?;
        }
        Ok(())
    })?;
    set(globals, "MEMCARDMAN", memcardman, call)?;
    let unlockman = object(call, |call, owner| {
        for name in [
            "GetNumUnlocks",
            "GetNumUnlocked",
            "GetPoints",
            "GetPointsForProfile",
            "GetPointsUntilNextUnlock",
            "IsSongLocked",
            "IsCourseLocked",
            "IsStepsLocked",
        ] {
            value_method(call, owner, name, 0_i32)?;
        }
        value_method(call, owner, "AnyUnlocksToCelebrate", false)?;
        value_method(call, owner, "GetUnlockEntryIndexToCelebrate", -1_i32)?;
        for name in ["FindEntryID", "GetUnlockEntry"] {
            value_method(call, owner, name, Value::Nil)?;
        }
        empty_method(call, owner, "GetSongsUnlockedByEntryID", 1)?;
        empty_method(call, owner, "GetStepsUnlockedByEntryID", 2)?;
        for name in [
            "PreferUnlockEntryID",
            "UnlockEntryID",
            "UnlockEntryIndex",
            "LockEntryID",
            "LockEntryIndex",
        ] {
            effect_method(call, owner, name, Value::Table(owner))?;
        }
        Ok(())
    })?;
    set(globals, "UNLOCKMAN", unlockman, call)?;
    let hooks = object(call, |call, owner| {
        value_method(call, owner, "GetArchName", crate::song_lua_arch_name())?;
        value_method(call, owner, "GetClipboard", "")?;
        for name in ["SetClipboard", "OpenFile", "OpenURL", "RestartProgram"] {
            effect_method(call, owner, name, Value::Boolean(false))?;
        }
        Ok(())
    })?;
    set(globals, "HOOKS", hooks, call)
}

fn empty_tables(call: &mut HostCall<'_>) -> Result<(), Error> {
    let count = *call.function_data::<usize>().expect("result count");
    for _ in 0..count {
        let result = call.try_new_table()?;
        call.push(Value::Table(result))?;
    }
    Ok(())
}

fn effect(call: &mut HostCall<'_>) -> Result<(), Error> {
    side_effect(call, call.captures()[1], call.captures()[2])?;
    call.push(call.captures()[0])
}

fn styles(call: &mut HostCall<'_>) -> Result<(), Error> {
    // The production host returns a fresh single-style list for every request,
    // independent of the requested game or the session's current style.
    let result = object(call, |call, result| {
        let style = style(call, "single")?;
        set(result, 1_i32, style, call)
    })?;
    call.push(Value::Table(result))
}

pub(super) fn style(call: &mut HostCall<'_>, key: &str) -> Result<TableId, Error> {
    let info = crate::song_lua_style_info(key);
    object(call, |call, owner| {
        set(owner, "__songlua_style_key", key, call)?;
        value_method(call, owner, "GetName", info.name)?;
        value_method(call, owner, "GetStepsType", info.steps_type)?;
        value_method(call, owner, "GetStyleType", info.style_type)?;
        value_method(call, owner, "ColumnsPerPlayer", info.columns)?;
        value_method(call, owner, "GetWidth", info.width)?;
        let method = call.new_host_function_with_data(column, &[], info)?;
        set(owner, "GetColumnInfo", method, call)
    })
}

fn column(call: &mut HostCall<'_>) -> Result<(), Error> {
    let info = *call
        .function_data::<crate::SongLuaStyleInfo>()
        .expect("style metadata");
    let index = integer(call, arg(call, 1))
        .unwrap_or(1)
        .clamp(1, info.columns as i32) as usize
        - 1;
    let result = object(call, |call, result| {
        set(
            result,
            "Name",
            crate::song_lua_style_column_name(index),
            call,
        )?;
        set(result, "Track", index, call)?;
        set(
            result,
            "XOffset",
            crate::song_lua_style_column_x(info.name, index),
            call,
        )
    })?;
    call.push(Value::Table(result))
}
